var RECIPES=[{"id":"biryani","country":"Pakistan","name":"Chicken Biryani","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":60,"diff":"Medium","servings":"4 people","img":"assets/hero-49347f9b.webp","videos":{"en":"a6k4gpStnX0","ru":"ZeGEe2sKvHQ","hi":"HLLFfmH_rsg","es":"6wHV6tBKnjI","fr":"4l_INHwgeTY","ar":"lfgY7JVpkN8","pt":"usNzvglYMYA","rus":"ApkU_NqpT_c","zh":"k7ogYWfE6Zs","ja":"TtNBr6ZnLpE","de":"96iuaCOSwEg","tr":"IIHiUDS9_f8","bn":"AVc1vL_6QUc"},"shape":"tall","alt":"A plate of chicken biryani with saffron rice and fresh coriander","desc":"Karachi-style biryani, spiced chicken, fragrant basmati and the dum aroma that fills the whole house.","intro":"Biryani is not just food, it is a feast. Marinate the chicken in yoghurt and spices, boil the rice halfway, then put it on dum, masala below, rice on top, and the colour in between that makes every bite special.","ing":["Chicken 750g, yoghurt 1 cup","Basmati rice 3 cups, soaked","Biryani masala 3 tbsp, ginger-garlic paste 2 tbsp","Onions 3, browned","Tomatoes 2, green chillies 4","Fresh coriander, mint, lemon","Saffron / food colour, ghee 3 tbsp"],"steps":["Mix yoghurt, masala and ginger-garlic into the chicken and marinate for 30 minutes.","Boil the rice with salt and whole spices until 70% cooked, then drain.","Brown the onions, add tomatoes and the marinated chicken, and fry the masala well.","Layer masala first, then rice, and top with onions, coriander and saffron.","Cover and cook on low heat on dum for 20 minutes, then mix gently and serve."],"tip":"Do not over-boil the rice, it will finish cooking on dum. Put a cloth over the lid on dum so the steam does not escape.","published":"2026-10-28"},{"id":"nihari","country":"Pakistan","name":"Beef Nihari","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":90,"diff":"Hard","servings":"5 people","img":"assets/trend-card-1-20dab29d.webp","video":"Ttifj2d5Aeo","videos":{"en":"Ttifj2d5Aeo","ru":"caDmv7OgvDo","hi":"y4weMzw_pRk","es":"jlExGSGRh5g","fr":"m0gzVcrC2n8","ar":"Xdw4ZkYwfDI","pt":"lyV2RmM8GmU","rus":"KbHSZhTaZ5Q","zh":"ZD8_Dhmx4xo","ja":"Q7Y-RxXQjnk","de":"_poiVshOkzw","tr":"ReekW3qCqMU","bn":"VZg4m8rbvVg"},"shape":"tall","alt":"A bowl of beef nihari with deep masala and ginger","desc":"Slow-cooked nihari, tender meat, deep masala and the gravy that finishes with naan.","intro":"Nihari is not fast food, it is food of patience. Cook the meat on low heat for hours, until it falls off the bone and the gravy takes on its deep colour and flavour.","ing":["Beef (shank) 1 kg","Nihari masala 4 tbsp, flour 3 tbsp","Ginger-garlic paste 2 tbsp, onion 1","Ghee / oil ½ cup","Ginger, green chilli, lemon, for garnish","Fresh coriander"],"steps":["Lightly brown the onion in ghee, add ginger-garlic and fry.","Add the meat and nihari masala and fry well.","Add water, cover, and cook on low heat for 2 hours.","Dissolve flour in water, add it, and cook until the gravy thickens.","Serve with naan, garnished with ginger, green chilli, lemon and coriander."],"tip":"Do not keep the gravy thin, nihari is known for its thick, glossy gravy. Add the flour slowly so no lumps form.","published":"2026-10-28"},{"id":"karahi","country":"Pakistan","name":"Chicken Karahi","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":40,"diff":"Easy","servings":"4 people","img":"assets/chicken-karahi-72a3c2f2.webp","videos":{"en":"31ZEPj6qgZo","ru":"KInsyNWiyb4","hi":"Pf1aHakuogg","es":"iJ-PU15qqF0","fr":"cDrI9MgBsKA","ar":"SnacSWi9gBY","pt":"trQJm95pIxE","rus":"MgZF7YyMoBs","zh":"NJniWRtrcik","ja":"2bFIaEL2mx8","de":"Los0i1g2bik","tr":"WLxPEk76izk","bn":"LKAmurfdzIg"},"shape":"wide","alt":"Chicken karahi in a kadhai with tomatoes and green chillies","desc":"Dhaba-style karahi, fresh tomatoes, ginger and green chillies, exactly the taste you get at a karahi dhaba.","intro":"The secret of karahi is fresh tomatoes and high heat. No onion is needed, the tomato water itself becomes the masala, and ginger and green chillies at the end complete it.","ing":["Chicken 750g, tomatoes 4 large","Ginger-garlic paste 1 tbsp","Green chillies 4, ginger julienne","Ghee / oil ½ cup","Salt, crushed red chilli, garam masala","Fresh coriander"],"steps":["Heat ghee in a kadhai and fry the chicken on high heat.","Add ginger-garlic, then tomatoes, and cover.","When the tomatoes soften, mash them with a spoon and fry the masala.","When the oil rises to the top, add green chillies, ginger and garam masala.","Give 5 minutes of dum, add coriander, and serve with roti or naan."],"tip":"Do not add water to karahi, the tomatoes' own water is enough. Keep the heat high so the chicken stays tender and the masala well fried.","published":"2026-10-28"},{"id":"daal","country":"India","name":"Daal Fry (Tadka Daal)","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":35,"diff":"Easy","servings":"4 people","img":"assets/daal-fry-tadka-daal-699cd89e.webp","video":"jitAtR8tGGA","videos":{"en":"jitAtR8tGGA","ru":"1K3X89HNBO8","hi":"AaCjTyS2u8Q","es":"zWCxgvM3pNg","fr":"s2uxxx0mqEs","ar":"OTjIbN7HNHA","pt":"pklhukPqbQc","rus":"J_GPRbuckeI","zh":"P39NMRaLets","ja":"xADNTG9bGY4","de":"Sr-noLQ-ycc","tr":"Cg62q-eDHTg","bn":"n31uDmqFyK0"},"shape":"tall","alt":"A bowl of tadka daal with red chilli and cumin tempering","desc":"Home-style daal with a cumin and red chilli tadka on top, perfect with rice or roti.","intro":"Daal is every home's daily food, but the tadka makes it special. Boil the daal until soft, then temper cumin, garlic and whole red chillies in ghee, the aroma alone is enough.","ing":["Masoor / moong daal 1½ cups","Turmeric ½ tsp, salt","Garlic 4 cloves, cumin 1 tsp","Whole red chillies 3, ghee 3 tbsp","Green chilli, fresh coriander, lemon"],"steps":["Wash the daal and boil with turmeric and water until soft.","Fry cumin and garlic in ghee until golden, add the red chillies.","Pour the tadka over the daal at once and cover for 2 minutes.","Add green chilli and coriander and mix.","Serve hot with rice or roti."],"tip":"Cover the daal as soon as you pour the tadka, this keeps the aroma inside the daal instead of letting it escape.","published":"2026-10-28"},{"id":"chapli","country":"Pakistan","name":"Chapli Kabab","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":30,"diff":"Medium","servings":"4 people","img":"assets/chapli-kabab-23a29baa.webp","videos":{"en":"mv9tF5mN1Bk","ru":"spv0xat-Ogo","hi":"4Bm9MAEACWU","es":"JigVx5T72pw","fr":"BYQKWyk5PTQ","ar":"Jo2vYgEYFlQ","pt":"_-5b9Zqm9D4","rus":"cKHz2gQvt2g","zh":"S8ZCjPFO-JM","ja":"Y5JyZCYx-Uc","de":"u2yaPP3icS8","tr":"RHsFRrRuMUo","bn":"Rh-RVKXoFrY"},"shape":"wide","alt":"A plate of chapli kebabs with green chutney and salad","desc":"Peshawari chapli kebab, pomegranate seeds, tomato and the masala you feel in every bite.","intro":"Chapli kebab means flat, soft and spicy. Mix tomato, pomegranate seeds and whole spices into the mince, flatten it by hand, then fry both sides on a tawa.","ing":["Beef mince 500g","Tomato 1 finely chopped, onion 1","Pomegranate seeds 1 tbsp, crushed whole coriander","Green chillies 3, ginger, salt","Maize flour 2 tbsp","Oil for frying"],"steps":["Mix tomato, onion, spices and maize flour into the mince and rest for 20 minutes.","With wet hands, make flat kebabs and press a tomato piece in the centre.","Heat oil on a tawa and fry the kebabs on low heat.","When golden on both sides, remove them.","Serve with green chutney, onion and naan."],"tip":"Do not press the kebabs too much, turn them gently or they will break. Cold mince makes better kebabs.","published":"2026-10-28"},{"id":"tikka","country":"Pakistan","name":"Chicken Tikka","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":45,"diff":"Easy","servings":"4 people","img":"assets/chicken-tikka-07347e22.webp","videos":{"en":"1tQ4kCSA66k","ru":"xDxs9BqlM8w","hi":"m4siRREwvAA","es":"cWocEvSPzTA","fr":"aci3XL8qzbc","ar":"YnrAwjGcvbk","pt":"Q5UlXjR3Nr4","rus":"UtbL88KdcwA","zh":"5_8FkLKEdw0","ja":"RwCLOOKuQlM","de":"Oa-MyBFczSI","tr":"sfXmFA6CqZ8","bn":"QG_PSAXSt2Q"},"shape":"tall","alt":"Chicken tikka pieces with spices and char aroma","desc":"Tandoori-style chicken tikka, marinated in yoghurt and spices, finished with lemon and chaat masala.","intro":"Good tikka comes from marination. Keep chicken in yoghurt, red chilli and garam masala for at least 1 hour, then grill on high heat, lightly charred outside, juicy inside.","ing":["Chicken (leg / boneless) 750g","Yoghurt ½ cup, red chilli 1 tbsp","Turmeric, garam masala, cumin powder","Ginger-garlic paste 1 tbsp, lemon 1","Oil / butter for brushing"],"steps":["Make a paste of yoghurt, all spices and ginger-garlic.","Score the chicken, coat it well with masala, and rest for 1 hour.","Grill on high heat, brushing with butter in between.","When golden and charred on both sides, remove.","Sprinkle lemon and chaat masala and serve."],"tip":"The longer the marination, the softer the tikka. If time is short, give it at least 30 minutes.","published":"2026-10-28"},{"id":"halwapuri","country":"Pakistan","name":"Halwa Puri Nashta","cat":"nashta","catLabel":"Breakfast","veg":"veg","time":50,"diff":"Medium","servings":"4 people","img":"assets/halwa-puri-nashta-43dc5fe8.webp","videos":{"en":"yTGbGsFZg8Q","ru":"Td1UYcSSmbE","hi":"348Ccq2Bv9s","es":"g7oPPsPlRK0","fr":"9uRHYaKHNwo","ar":"36I6VmxYQGQ","pt":"A19CVQvJ1OQ","rus":"KaMxBL-Pwao","zh":"2zjF5Mv4Wsk","ja":"hGiZ9BAfg2s","de":"Ek6Mifk-BTw","tr":"15JBR6FjXoE","bn":"LEboQELi-KE"},"shape":"wide","alt":"Halwa puri breakfast, puffed puri, halwa and chickpeas","desc":"Sunday breakfast, puffed puri, soft semolina halwa and spiced chickpeas, just like Lahore.","intro":"Halwa puri is not breakfast, it is a tradition. Puffed puri, soft halwa and spiced chickpeas, the combination of all three is the soul of this breakfast.","ing":["Flour 2 cups, semolina 1 cup","Sugar 1 cup, ghee ½ cup","Chickpeas (boiled) 2 cups","Potato 1, onion, tomato","Garam masala, turmeric, red chilli","Cardamom, almonds for garnish"],"steps":["Knead the flour, roll small puris and deep-fry in hot oil until puffed.","Roast semolina in ghee, add sugar syrup and make halwa.","Cook chickpeas with masala, potato and tomato.","Add cardamom and almonds to the halwa.","Serve puri, halwa and chickpeas together."],"tip":"Do not use too much flour while rolling puri, or it will not puff. If the oil is well heated, the puri puffs at once.","published":"2026-10-28"},{"id":"samosa","country":"India","name":"Punjabi Samosa","cat":"street","catLabel":"Street Food","veg":"veg","time":45,"diff":"Medium","servings":"6 people","img":"assets/punjabi-samosa-307fb89d.webp","videos":{"en":"AtUpMrfILW0","ru":"xYdOlbSqAN4","hi":"XYuZbpmxF2A","es":"uZqNpuPd2x8","fr":"v2pShTwy9VY","ar":"fyTHjioGeEA","pt":"hkPoukSOioY","rus":"Iu-Fs4IUE54","zh":"JnVVP--9F_s","ja":"KT2QlrQeVhE","de":"4D62lTb2EOQ","tr":"OlZuHJrPoKY","bn":"Vtp-0JePB74"},"shape":"wide","alt":"A plate of samosas with chutney","desc":"Crispy Punjabi samosa, spiced potato, green chutney and tea, the best evening pair.","intro":"A samosa lives in its crisp pastry and spiced potato. Knead the flour firm, mix garam masala and coriander into the potato, then fry on low heat, the pastry will be golden and crisp.","ing":["Flour 2 cups, carom seeds ½ tsp","Potatoes (boiled) 4, peas ½ cup","Ginger, green chilli, garam masala","Fresh coriander, pomegranate seeds","Oil for frying"],"steps":["Mix carom seeds and ghee into the flour, knead a firm dough, and rest for 20 minutes.","Mash the potatoes and mix in spices, peas and coriander.","Roll the dough, shape samosas and fill with the mixture.","Seal the edges well and fry on low heat until golden.","Serve with green and tamarind chutney."],"tip":"Always fry samosas on low heat, on high heat the pastry will burn and the inside will stay raw.","published":"2026-10-28"},{"id":"bunkebab","country":"Pakistan","name":"Bun Kebab","cat":"street","catLabel":"Street Food","veg":"nonveg","time":25,"diff":"Easy","servings":"4 people","img":"assets/bun-kebab-fca6f5e9.webp","videos":{"en":"7U6PEk1Mx_M","ru":"_sNEDLn_FvI","hi":"PdeTc8dIiTA","es":"8NLgSqEuRUc","fr":"xvNLzlklqZE","ar":"jEhVffen_gs","pt":"85RY3SIDhBc","rus":"LCBwfPIID2I","zh":"pJVqxh65Ivk","ja":"7tjqOWnxmJU","de":"U_MLxDnELlo","tr":"rhUTm67kXY8","bn":"d5Umsd6LG0g"},"shape":"square","alt":"Bun kebab, kebab, onion and chutney inside a bun","desc":"Karachi street-style bun kebab, shami kebab, tamarind chutney and onion, packed in a bun.","intro":"Bun kebab is Karachi's identity. Fry shami kebabs on a tawa, place them in a bun, add onion, tomato and tamarind chutney, every bite has the perfect balance of masala and chutney.","ing":["Shami kebabs 8, buns 4","Onion, tomato, green chutney","Tamarind chutney, yoghurt","Green chilli, fresh coriander","Butter for toasting the bun"],"steps":["Fry the shami kebabs in a little oil on both sides.","Butter the buns and lightly toast them on the tawa.","Spread chutney on the bun and place the kebab.","Add onion, tomato and green chilli.","Close the bun and serve hot."],"tip":"Do not over-toast the bun, lightly golden is enough, or it will become hard.","published":"2026-10-28"},{"id":"gulabjamun","country":"India","name":"Gulab Jamun","cat":"meetha","catLabel":"Desserts","veg":"veg","time":40,"diff":"Medium","servings":"6 people","img":"assets/trend-card-2-009bdad8.webp","videos":{"en":"8U7omAUUqG8","ru":"ZmmQtyGiqWU","hi":"Y0VaRwnMIgs","es":"5kdJK92pJjI","fr":"2jWmZf88wp4","ar":"PK-5g7SCmeo","pt":"WLyT-yJCrWc","rus":"xmDOwJ0ME8A","zh":"B_-AArSbDK4","ja":"vEfgouGUcqI","de":"eZjSwgpJih8","tr":"9hEZjAOILxU","bn":"sj_MSCQ3N5c"},"shape":"tall","alt":"Gulab jamun in syrup with rose aroma","desc":"Soft gulab jamun, khoya, syrup and cardamom, the most-loved sweet for Eid and feasts.","intro":"Gulab jamun turn soft when the khoya is good and the syrup is lightly warm. Fry the jamuns on low heat, then put them in syrup for 1 hour, they will drink the syrup and swell.","ing":["Khoya 250g, flour 3 tbsp","Cardamom powder ½ tsp","Sugar 2 cups, water 2 cups","Rose water 1 tsp, 2 drops of lemon","Oil / ghee for frying"],"steps":["Mix khoya and flour into a soft dough and make small balls.","Make syrup from sugar and water, add cardamom and rose water.","Fry the jamuns on low heat until lightly golden.","Put the hot jamuns into the warm syrup.","Rest for 1 hour, then serve."],"tip":"The jamuns should have no cracks, grease your hands lightly with ghee while shaping the balls. The syrup should not be too hot, or the jamuns will harden.","published":"2026-10-28"},{"id":"gajarhalwa","country":"India","name":"Gajar Ka Halwa","cat":"meetha","catLabel":"Desserts","veg":"veg","time":55,"diff":"Medium","servings":"5 people","img":"assets/gajar-ka-halwa-fc5f08bf.webp","videos":{"en":"CVaE76tT-1U","ru":"cpNu3H_40rY","hi":"wizd84RWb7o","es":"QOyLKv0VHDw","fr":"0rCtlfmvVTA","ar":"WRJx_pi9aw4","pt":"8DTJqlVDtWY","rus":"llYQMSQLUgA","zh":"gGot_BXyMh8","ja":"4cl0-sYknlM","de":"h2ahtV9CjfQ","tr":"lm8ktGbDXkE","bn":"TFxuoO__vkY"},"shape":"tall","alt":"Gajar ka halwa with khoya and almonds","desc":"Winter gajar ka halwa, red carrots, milk, khoya and ghee, just like home.","intro":"Gajar ka halwa needs patience. Cook the carrots in milk on low heat; when the milk dries, add ghee and sugar, and finish with khoya and almonds, the best winter aroma.","ing":["Red carrots 1 kg, grated","Milk 1 litre, sugar 1 cup","Ghee 4 tbsp, khoya 150g","Cardamom 4, almonds / pistachios"],"steps":["Put carrots and milk in a kadhai and cook on low heat.","When the milk dries, add ghee and fry.","Add sugar and cook until the halwa leaves the kadhai.","Mix in khoya and cardamom and cook for 5 minutes.","Add almonds and pistachios and serve."],"tip":"Grate the carrots finely, thick carrots take longer to cook and the halwa stays coarse.","published":"2026-10-28"},{"id":"lassi","country":"India","name":"Mango Lassi","cat":"drinks","catLabel":"Drinks","veg":"veg","time":15,"diff":"Easy","servings":"3 people","img":"assets/mango-lassi-bb084ab7.webp","videos":{"en":"8n7XRXqyfZ0","ru":"2J2mSFW-t8c","hi":"s3w8bhPWQcE","es":"gQi4yC7X5Oc","fr":"4AxP0JVVi1s","ar":"U5N41RTi6vE","pt":"3D9NGTw7wl8","rus":"0d3TUPDOJ9g","zh":"1T8CuVO_3vI","ja":"oRjLjG8VSys","de":"2pQ6NubFbnw","tr":"DcDrjRckXfU","bn":"Iq4Yi0B-Q7k"},"shape":"tall","alt":"A glass of mango lassi with mango and mint","desc":"Chilled mango lassi, ripe mangoes, yoghurt and cardamom, the most soothing drink in summer.","intro":"Mango lassi is summer's answer. Take ripe, sweet mangoes, add cold yoghurt and cardamom aroma, 1 minute in the blender, and comfort in a glass.","ing":["Ripe mangoes 2, yoghurt 1½ cups","Milk ½ cup, sugar 2 tbsp (to taste)","Cardamom powder ¼ tsp","Ice cubes, mint for garnish"],"steps":["Peel the mangoes and cut into pieces.","Put mango, yoghurt, milk and sugar in a blender.","Add cardamom and ice and blend for 1 minute.","Pour into glasses and garnish with mint.","Serve chilled at once."],"tip":"The sweeter the mango, the less sugar you need. Do not make lassi in advance, freshly blended is best.","published":"2026-10-28"},{"id":"pizza","name":"Margherita Pizza","cat":"world","catLabel":"World Food","country":"Italy","veg":"veg","time":75,"diff":"Medium","servings":"4 people","img":"assets/margherita-pizza-22ce327b.webp","videos":{"en":"GPn_absd5b8","ru":"CAoqkV4uOmM","hi":"kBZKJdYfd7k","es":"0vvLyH25m9A","fr":"5OVYwjYZktI","ar":"Rf_8mSSh4SQ","pt":"LW66CzyiHvk","rus":"SIU45MxcRGg","zh":"7lfBEizLP2A","ja":"bDxzMga31zI","de":"mWpdOn0Lmt8","tr":"oU1Ar-hjSkI","bn":"Bg0WQKoWdG8"},"shape":"tall","alt":"A margherita pizza with tomato sauce, melted mozzarella and fresh basil","desc":"From Italy, a classic Neapolitan pizza with tomato, fior di latte mozzarella and fresh basil.","intro":"Margherita pizza is proof that simple food can be extraordinary. It was made famous in Naples, where a hot oven, a thin crust, bright tomato sauce and good mozzarella do all the work. The colours are said to echo the Italian flag, red tomato, white mozzarella and green basil, and the flavour is clean and fresh rather than heavy. This version uses a dough that rests long enough to become light and chewy, a sauce that is barely cooked, and a very hot oven so the crust blisters in minutes. Take time with the dough and the heat, and the pizza will taste like a pizzeria pizza, even from a home oven.","ing":["Strong bread flour 500g, warm water 325ml","Instant yeast 7g, fine salt 10g, olive oil 2 tbsp","San Marzano tomatoes 400g, crushed","Fior di latte mozzarella 250g, torn","Fresh basil leaves 1 handful","Garlic 1 clove, olive oil and salt for the sauce","Semolina or flour for dusting"],"steps":["Mix the flour, water, yeast and salt, knead for 8 to 10 minutes until smooth, then rest the dough covered for 1 hour, or overnight in the fridge for better flavour.","Crush the tomatoes with garlic, a pinch of salt and 1 tbsp of olive oil. Do not cook the sauce, it cooks on the pizza.","Divide the dough into 4 balls, rest for 20 minutes, then stretch each one by hand from the centre out, leaving a thicker edge.","Heat the oven as hot as it will go, at least 250C, with a pizza stone or an upside down baking tray inside for 30 minutes.","Spread 3 to 4 tbsp of sauce on each base, leaving the edge clear, and scatter the torn mozzarella over the top."],"tip":"Do not overload the pizza. A thin layer of sauce and a modest amount of cheese let the crust cook through and stay crisp.","published":"2026-10-28"},{"id":"carbonara","name":"Spaghetti Carbonara","cat":"world","catLabel":"World Food","country":"Italy","veg":"nonveg","time":25,"diff":"Easy","servings":"4 people","img":"assets/spaghetti-carbonara-50bc65b0.webp","videos":{"en":"LhbQ7bdXsXw","ru":"oAPq18l_fZc","hi":"aw4YLP_9wPE","es":"2PWUYr2sAY0","fr":"kS3nyQBQDU0","ar":"xl4F2rvhh0o","pt":"JE-s4DCDTFw","rus":"soNNe3NBsWE","zh":"Gq5Z0sCEjIs","ja":"9zBmYPvAOiE","de":"S4v21Az_PqU","tr":"dMo3K18BkKY","bn":"vtqLG5GqT6w"},"shape":"square","alt":"Spaghetti carbonara with pancetta, egg sauce and grated pecorino","desc":"From Italy, silky spaghetti carbonara made with eggs and pecorino, with no cream at all.","intro":"Real carbonara has no cream. It comes from Rome, and its sauce is made only from eggs, pecorino cheese, black pepper and the fat from guanciale or pancetta, mixed with hot pasta until it turns glossy and silky. The trick is heat control. The pan must be hot enough to cook the eggs gently into a sauce, but never so hot that they scramble. Work quickly, use pasta water to loosen the sauce, and serve at once. Once you learn the timing, this becomes one of the fastest and most comforting pasta dishes you can make, with only a handful of ingredients and a depth of flavour that tastes far more complex than it is.","ing":["Spaghetti 400g","Guanciale or pancetta 150g, diced","Egg yolks 4, plus 1 whole egg","Pecorino Romano 60g, finely grated","Black pepper 2 tsp, freshly cracked","Salt for the pasta water","Extra pecorino and pepper to serve"],"steps":["Boil the spaghetti in well salted water until just al dente, and keep 1 cup of the pasta water before draining.","Fry the guanciale or pancetta in a dry pan on medium heat for 6 to 8 minutes until crisp at the edges and the fat has melted out.","Whisk the yolks, whole egg, pecorino and most of the black pepper into a thick paste. Add a spoon of pasta water if it is too stiff.","Take the pan off the heat and let it cool for 1 minute, so the eggs will not scramble when they meet the pan.","Add the drained spaghetti to the pan and toss well in the rendered fat for 30 seconds."],"tip":"Take the pan off the heat before adding the eggs. Residual heat makes the sauce, direct heat makes scrambled eggs.","published":"2026-10-28"},{"id":"sushi","name":"Sushi","cat":"world","catLabel":"World Food","country":"Japan","veg":"nonveg","time":50,"diff":"Medium","servings":"4 people","img":"assets/sushi-2508fc3b.webp","videos":{"en":"bcrnzvui6Cw","ru":"BAyH7vj5IgM","hi":"KtnXv8NBm4g","es":"Qr0Iz1Hm6WI","fr":"5ZEsPyN0gUI","ar":"yPJabifcraY","pt":"mNSW1VbcGC0","rus":"mzPE_gcPrvw","zh":"OXLK5Dkwqe8","ja":"_BmKR5EfwJ4","de":"KrRubWbw4zY","tr":"oGt0-iPxQLE","bn":"aqVp6OPPZ5c"},"shape":"tall","alt":"Salmon and cucumber sushi rolls with rice, nori and sesame seeds","desc":"From Japan, salmon and cucumber sushi rolls with seasoned rice, nori and a little wasabi.","intro":"Sushi is about rice first and fish second. In Japan, the rice is seasoned with vinegar, sugar and salt, fanned cool, and handled gently so every grain stays separate and glossy. This home version makes salmon and cucumber rolls, the kind that are easiest to learn, with nori on the outside, rice in the middle, and a neat line of filling. Use sushi grade salmon, keep your hands wet, and roll firmly but gently. The first roll may look uneven, and that is normal. By the third roll, the shape, the cut and the confidence all come together, and the result tastes fresh, clean and far better than shop bought sushi that has sat in a fridge.","ing":["Sushi rice 2 cups, uncooked","Rice vinegar 4 tbsp, sugar 2 tbsp, salt 1 tsp","Nori sheets 4","Sushi grade salmon 300g, cut into strips","Cucumber 1, cut into thin sticks","Mayonnaise 3 tbsp, sriracha 1 tsp, for spicy mayo","Soy sauce, pickled ginger and wasabi to serve","Sesame seeds 1 tbsp, optional"],"steps":["Rinse the rice until the water runs clear, cook it, then rest it covered for 10 minutes.","Warm the vinegar, sugar and salt until dissolved, fold it into the hot rice with a slicing motion, and fan the rice until it is just warm and glossy.","Lay a nori sheet shiny side down on a bamboo mat, wet your hands, and spread a thin even layer of rice, leaving 2cm bare at the far edge.","Spread a thin line of spicy mayo across the centre, add salmon and cucumber sticks in a neat row, and sprinkle with sesame seeds.","Lift the near edge of the mat and roll firmly away from you, tucking the filling in, and press gently to seal the bare edge with a little water."],"tip":"Keep a bowl of water nearby and wet your hands and knife often. Wet hands stop the rice sticking, and a wet blade cuts cleanly without squashing the roll.","published":"2026-10-28"},{"id":"ramen","name":"Ramen","cat":"world","catLabel":"World Food","country":"Japan","veg":"nonveg","time":45,"diff":"Medium","servings":"4 people","img":"assets/ramen-e463426c.webp","videos":{"en":"mWFDKl2dcJQ","ru":"FEH60cUxhqA","hi":"td680CiO9jE","es":"QvYYqhlZEGQ","fr":"6TURngkWT7Q","ar":"GIEQmm41JE4","pt":"7EKK-PNdKh0","rus":"0iNHiXsRRec","zh":"zKj8wUrSEHU","ja":"x3BTNnmlt8Q","de":"PQt0BbiHyUQ","tr":"OYVoQ3t_HJ4","bn":"9-Mvk6kPLxk"},"shape":"tall","alt":"A bowl of chicken ramen with noodles, egg, chicken and spring onions","desc":"From Japan, chicken ramen with a rich broth, springy noodles, a soft egg and fresh toppings.","intro":"Ramen is comfort in a bowl, and a good home version does not need a broth that simmers all day. This chicken ramen builds flavour quickly, with garlic, ginger and spring onions fried in sesame oil, chicken stock enriched with soy and miso, and noodles cooked separately so the broth stays clear and the noodles stay springy. The egg is the finishing touch, soft in the middle and seasoned by the broth as you eat. Set out the toppings in small bowls and let everyone build their own bowl, hot broth last, so the noodles do not sit and soften. It is fast, warming and deeply satisfying, and it tastes like care, not like a shortcut.","ing":["Chicken breasts or thighs 500g","Chicken stock 1.5 litres","Ramen noodles 4 portions","Garlic 4 cloves, ginger 3cm piece","Soy sauce 3 tbsp, miso paste 2 tbsp","Sesame oil 1 tbsp, spring onions 4","Eggs 4, soft boiled","Chilli oil, sesame seeds and nori to serve"],"steps":["Boil the eggs for 6 and a half minutes, cool in cold water, peel, and halve them just before serving.","Heat sesame oil in a large pot, fry the garlic, ginger and the white parts of the spring onions for 2 minutes until fragrant.","Pour in the chicken stock, add soy sauce, and simmer gently for 15 minutes so the flavours come together.","Cook the chicken in the simmering broth for 12 to 15 minutes until cooked through, then lift it out, slice it, and keep it warm.","Whisk the miso with a ladle of hot broth until smooth, then stir it back into the pot. Do not boil hard after adding miso."],"tip":"Cook the noodles separately. Noodles cooked in the broth soak it up, turn the broth cloudy, and go soft before you serve.","published":"2026-10-28"},{"id":"tacos","name":"Tacos al Pastor","cat":"world","catLabel":"World Food","country":"Mexico","veg":"nonveg","time":40,"diff":"Medium","servings":"4 people","img":"assets/tacos-al-pastor-24ef06b9.webp","videos":{"en":"lUjUKRD1sBA","ru":"ZCAw85u6rKE","hi":"IWfu144rA_M","es":"7gcdEFfrh7A","fr":"puHuNGY5kJU","ar":"B0U91ewVFBI","pt":"RoS6Q19ouho","rus":"iqyb5SSCOcM","zh":"vgZw1QfXPfQ","ja":"9EuAICP3gRk","de":"BJMd2OJ39yc","tr":"sEYpEeoPKGA","bn":"JzTaIM4sW8k"},"shape":"tall","alt":"Tacos al pastor with marinated pork, pineapple, onion and coriander","desc":"From Mexico, tacos al pastor with chilli marinated pork, charred pineapple, onion and coriander.","intro":"Tacos al pastor began with Lebanese shawarma cooking in Mexico City, and it became something entirely Mexican, pork marinated in dried chillies and achiote, cooked until charred at the edges, and served in warm corn tortillas with pineapple, onion and coriander. The marinade does the heavy work, so give it time, even 30 minutes makes a difference, and overnight is better. Cook the pork hot and fast so it chars without drying out, warm the tortillas over an open flame or in a dry pan, and keep the toppings simple. The sweet pineapple against the smoky, spiced pork is the whole point, so do not skip it, and serve with lime and salsa on the side.","ing":["Pork shoulder 700g, thinly sliced","Dried guajillo chillies 3, ancho chilli 1","Achiote paste 2 tbsp, garlic 3 cloves","White vinegar 3 tbsp, orange juice 60ml","Cumin 1 tsp, oregano 1 tsp, salt","Pineapple 300g, cut into chunks","Corn tortillas 12, white onion 1, coriander","Limes 2, salsa of your choice"],"steps":["Soak the dried chillies in hot water for 15 minutes until soft, then drain, keeping a little of the soaking water.","Blend the chillies, achiote, garlic, vinegar, orange juice, cumin, oregano and salt into a smooth marinade, adding soaking water as needed.","Coat the pork in the marinade, cover, and refrigerate for at least 30 minutes, or overnight for the best flavour.","Heat a large pan or griddle on high heat with a little oil, and cook the pork in batches for 3 to 4 minutes per side until charred and cooked through.","In the same hot pan, sear the pineapple chunks for 1 to 2 minutes per side until golden at the edges."],"tip":"Cook in batches and do not crowd the pan. Crowded pork steams instead of charring, and you lose the crisp edges that make al pastor special.","published":"2026-10-28"},{"id":"pozole","name":"Pozole","cat":"world","catLabel":"World Food","country":"Mexico","veg":"nonveg","time":150,"diff":"Hard","servings":"6 people","img":"assets/pozole-6cd83ab8.webp","videos":{"en":"AbCjZk-Dvyg","ru":"g--CmuQJmvs","hi":"HDM-3KgXTf4","es":"3p0DVrqDxJ0","fr":"huCe4f-vSj8","ar":"XG5Hu5JcE50","pt":"MuvgJhGD4E4","rus":"TJyM8dlXpd8","zh":"Jb5ailLg62E","ja":"d0qkJlAjpKY","de":"8YaUUOl7R4A","tr":"q9zN2n4o2Dc","bn":"zz_GrWDm_2w"},"shape":"wide","alt":"A bowl of red pozole with pork, hominy, radish, cabbage and lime","desc":"From Mexico, red pozole with slow cooked pork, hominy and a chilli broth, finished with fresh toppings.","intro":"Pozole is a celebration soup from Mexico, made with hominy, the large white corn kernels that puff and soften in a long simmer, and pork that cooks until it shreds with a spoon. The red version gets its colour and depth from dried guajillo and ancho chillies, blended smooth and stirred into the broth, while the toppings stay fresh and crisp, shredded cabbage, radish, onion, oregano and lime. It takes time, but most of that time is unattended, and the pot feeds a crowd. Cook it on a weekend, keep the broth rich and the toppings separate, and let everyone finish their own bowl at the table.","ing":["Pork shoulder 1kg, cut into large chunks","White hominy 800g, drained and rinsed","Dried guajillo chillies 4, ancho chillies 2","Onion 1, garlic 6 cloves","Bay leaves 2, oregano 2 tsp, cumin 1 tsp","Salt, water or light stock 3 litres","Shredded cabbage, radish, onion and lime to serve","Dried oregano and chilli flakes to serve"],"steps":["Soak the dried chillies in hot water for 15 minutes, drain, and blend with garlic and a little soaking water until smooth.","Put the pork, hominy, onion, bay leaves and water in a large pot, bring to a boil, and skim off any foam.","Reduce to a gentle simmer, cover partly, and cook for 90 minutes, topping up with hot water if the level falls too low.","Strain the blended chilli sauce through a sieve into the pot, stir well, and season with salt, cumin and oregano.","Simmer for 30 more minutes until the pork is tender enough to shred and the broth is rich and red."],"tip":"Strain the chilli sauce before adding it. The sieve catches skins and seeds, and the broth stays smooth and silky instead of gritty.","published":"2026-10-28"},{"id":"padthai","name":"Pad Thai","cat":"world","catLabel":"World Food","country":"Thailand","veg":"nonveg","time":30,"diff":"Medium","servings":"4 people","img":"assets/pad-thai-c0416eb6.webp","videos":{"en":"TmhcXcrc1Lc","ru":"-5Exi4Po3fw","hi":"dzKjG5qbJ10","es":"q4vD0Yjt_gI","fr":"nf_nzgCQAow","ar":"dMRw3kmgGIY","pt":"p-Re9qfHaIM","rus":"vbx4u1H4mpY","zh":"o0p8s0oazkQ","ja":"xyAOOJLyS2I","de":"ErU7xYilU5o","tr":"krIZwewEshE","bn":"QZSogSFPV4w"},"shape":"tall","alt":"Pad thai with rice noodles, prawns, egg, peanuts and lime","desc":"From Thailand, pad thai with rice noodles, prawns, egg, a sweet sour sauce and crunchy peanuts.","intro":"Pad thai is Thailand's most famous noodle dish, and its magic is balance, sweet, sour, salty and a little heat, all in one hot wok. The sauce is made from tamarind, fish sauce, palm sugar and chilli, and it coats rice noodles that are soaked, not boiled, so they stay springy instead of soft. Prawns, egg, bean sprouts and chives go in quickly, at high heat, and the dish is finished with crushed peanuts, lime and extra sprouts on the side. Have everything ready before you start, because once the wok is hot, the cooking takes only a few minutes, and that speed is what keeps the noodles from turning mushy.","ing":["Flat rice noodles 250g","Prawns 300g, peeled","Eggs 2, lightly beaten","Tamarind paste 3 tbsp, fish sauce 3 tbsp","Palm sugar or brown sugar 3 tbsp","Garlic 3 cloves, chilli flakes 1 tsp","Bean sprouts 2 cups, garlic chives or spring onions","Roasted peanuts 4 tbsp, crushed, lime 1"],"steps":["Soak the rice noodles in warm water for 20 to 30 minutes until pliable but still firm, then drain well.","Mix the tamarind, fish sauce, sugar and chilli flakes into a sauce, and taste it. It should be sweet, sour and salty at once.","Heat oil in a wok on high heat, fry the garlic for 20 seconds, then add the prawns and cook for 2 minutes until just pink.","Push the prawns to one side, pour in the eggs, and scramble them gently until just set, then mix with the prawns.","Add the drained noodles and the sauce, and toss constantly for 2 to 3 minutes until the noodles are tender and the sauce is absorbed."],"tip":"Soak the noodles, do not boil them. Boiled noodles overcook in the wok and turn soft and sticky.","published":"2026-10-28"},{"id":"pekingduck","name":"Peking Duck","cat":"world","catLabel":"World Food","country":"China","veg":"nonveg","time":180,"diff":"Hard","servings":"6 people","img":"assets/peking-duck-b271e564.webp","videos":{"en":"tIBJxtE2PEc","ru":"L7J1ro-RPOs","hi":"OibeXasbkTA","es":"3QSgzw-ptVk","fr":"l56lqPuFSt4","ar":"s1Fgx0KSwIQ","pt":"-IQUkXKm3HU","rus":"ZJrNBBcjj_8","zh":"h5TQvS7lrFs","ja":"0_UWLnd_o70","de":"ZjCcyUQ0yak","tr":"N2bxbla46hQ","bn":"c_HP-Z6zmsw"},"shape":"wide","alt":"A whole roast Peking duck with crisp golden skin on a platter","desc":"From China, Peking duck with crisp lacquered skin, served in thin pancakes with hoisin and spring onion.","intro":"Peking duck is one of China's great celebration dishes, famous for skin so crisp it shatters, and meat that stays juicy underneath. The secret is drying the skin and glazing it before roasting, so the fat renders out and the skin turns a deep lacquered red gold. This home version uses an overnight rest in the fridge to dry the skin, a simple maltose and vinegar glaze, and a hot oven, followed by a rest before carving. Serve it the traditional way, in thin mandarin pancakes with hoisin sauce, spring onion and cucumber, and let everyone assemble their own. It is a project, not a weeknight dinner, and it is worth every minute.","ing":["Whole duck 2 to 2.5kg","Maltose or honey 3 tbsp, rice vinegar 2 tbsp","Shaoxing wine 2 tbsp, five spice 1 tsp","Salt 1 tbsp, boiling water for blanching","Mandarin pancakes 12","Hoisin sauce 120ml","Spring onions 4, cucumber 1","Ginger and garlic for the cavity, optional"],"steps":["Clean the duck, pat it very dry, and prick the skin lightly all over with a fork, taking care not to pierce the meat.","Pour boiling water over the duck in the sink, which tightens the skin, then pat dry again.","Warm the maltose, vinegar, Shaoxing wine, five spice and salt until the maltose dissolves, and brush it all over the duck.","Rest the duck uncovered in the fridge overnight, on a rack over a tray, so the skin dries completely.","Roast breast side up at 200C for 30 minutes, then reduce to 180C and roast for 60 to 75 minutes more, until the skin is deep golden and crisp."],"tip":"Dry the skin overnight. Wet skin steams in the oven and never crisps, while dry skin renders and lacquers beautifully.","published":"2026-10-28"},{"id":"dimsum","name":"Dim Sum","cat":"world","catLabel":"World Food","country":"China","veg":"nonveg","time":60,"diff":"Medium","servings":"4 people","img":"assets/dim-sum-ffc63fc5.webp","videos":{"en":"e7583CDCJxM","ru":"d3nWoZlm6M8","hi":"-4dyLNLm4bI","es":"C1u9B-wcFFg","fr":"tPNtNclVI70","ar":"3jHF6ZYvl8Y","pt":"f2cpXZMaaMw","rus":"bDJ19InLxyU","zh":"jv5tHLTyvKw","ja":"oQOttPKd5Og","de":"W8rMgW3Zg4U","tr":"tCWIuZ11MzY","bn":"DF9Tms3SZvs"},"shape":"wide","alt":"Steamed dim sum dumplings in a bamboo steamer","desc":"From China, steamed dim sum with prawn and pork dumplings, served hot with chilli and soy dipping sauce.","intro":"Dim sum means food that touches the heart, and it is meant to be shared, small bamboo steamers arriving at the table one after another, each with a different bite inside. This home version makes two classics, prawn har gow with translucent wrappers, and pork and prawn siu mai with open tops, both steamed until just cooked and served hot. The wrappers need a light touch and a little patience, but the filling is simple, and the steaming is quick. Make them with help, one person filling, one person folding, and keep the finished dumplings covered so they do not dry out. Serve with tea, as in Cantonese yum cha, and let the meal stretch out slowly.","ing":["Prawns 300g, finely chopped","Pork mince 200g","Wheat starch 120g, tapioca starch 60g, for har gow","Wonton wrappers 20, for siu mai","Ginger 1 tbsp, grated, spring onions 2","Soy sauce 2 tbsp, sesame oil 1 tsp, white pepper","Sugar 1 tsp, Shaoxing wine 1 tbsp","Chilli oil, soy sauce and black vinegar to serve"],"steps":["Mix the prawns, pork, ginger, spring onions, soy, sesame oil, sugar, wine and white pepper into a filling, and chill for 20 minutes.","For har gow wrappers, mix wheat starch and tapioca starch with 180ml of just boiled water, knead into a smooth dough, and rest covered for 15 minutes.","Roll the har gow dough into a log, cut into small pieces, and press each one into a thin round with the side of a cleaver or a rolling pin.","Place a spoon of filling in each wrapper, fold into a crescent, and pleat the edge firmly, sealing the top.","For siu mai, place a spoon of filling in the centre of each wonton wrapper, gather the edges up around the filling, and press gently so the top stays open."],"tip":"Do not overfill the dumplings. A level teaspoon of filling seals neatly, while too much filling bursts the wrapper in the steamer.","published":"2026-10-28"},{"id":"coqauvin","name":"Coq au Vin","cat":"world","catLabel":"World Food","country":"France","veg":"nonveg","time":120,"diff":"Hard","servings":"4 people","img":"assets/coq-au-vin-a92f118c.webp","videos":{"en":"hlb2Jo9cyeE","ru":"-rR6XL2l704","hi":"uPvelNMxFBY","es":"oA1rxdBh-hU","fr":"xU1_C-O_hQ4","ar":"n_HWSK5Ig0g","pt":"0DTMrVybf2Q","rus":"CM0LpjsGxa8","zh":"d0Nm-iiIxYE","ja":"sWIxC0F_Kac","de":"Ea1SK4HjHYM","tr":"VWm3lpZjJ8g","bn":"JiRBKVye1qU"},"shape":"tall","alt":"Coq au vin, chicken braised in red wine with mushrooms and pearl onions","desc":"From France, coq au vin, chicken slowly braised in red wine with mushrooms, bacon and pearl onions.","intro":"Coq au vin is classic French comfort food, chicken braised slowly in red wine until it falls from the bone, with mushrooms, pearl onions and bacon in a sauce that tastes of the wine without tasting alcoholic. It comes from Burgundy, where the wine is part of the cooking, not just an accompaniment, and the long gentle braise is what makes the chicken tender and the sauce rich. Brown the chicken well first, because that colour becomes flavour, then let the pot do the work in the oven. Serve it with mashed potatoes or crusty bread, and give the sauce a final taste for salt and a little butter to make it shine.","ing":["Chicken thighs and legs 1kg, bone in","Red wine 500ml, Burgundy style if possible","Bacon lardons 150g","Mushrooms 250g, pearl onions 12","Carrot 1, garlic 3 cloves, thyme 3 sprigs","Chicken stock 250ml, tomato paste 1 tbsp","Flour 2 tbsp, butter 2 tbsp","Parsley to serve, salt and pepper"],"steps":["Season the chicken well, dust lightly with flour, and brown it in batches in a hot ovenproof pot until deep golden on both sides. Set aside.","Fry the bacon in the same pot until crisp, lift it out, and brown the mushrooms and pearl onions in the bacon fat.","Add the carrot, garlic and tomato paste, and cook for 2 minutes, stirring, until fragrant.","Pour in the wine, scraping the bottom of the pot to lift all the browned flavour, and simmer for 3 minutes.","Return the chicken and bacon to the pot, add stock and thyme, and bring to a gentle simmer. The liquid should come halfway up the chicken."],"tip":"Brown the chicken properly before braising. Pale chicken makes a pale sauce, while deep golden chicken makes a rich, full flavoured sauce.","published":"2026-10-28"},{"id":"bouillabaisse","name":"Bouillabaisse","cat":"world","catLabel":"World Food","country":"France","veg":"nonveg","time":75,"diff":"Hard","servings":"6 people","img":"assets/bouillabaisse-dd6562d3.webp","video":"W4XPwT4oJ4o","videos":{"en":"W4XPwT4oJ4o","ru":"paY1WXRB6G8","hi":"POGXp99MTPA","es":"Fr7w4vNrpAE","fr":"A9_aUTFvo4A","ar":"pCVTvPyYb7k","pt":"BKES6v6Bf6s","rus":"_0-K8IBVmrg","zh":"otZIzioKzcA","ja":"XE-SOmN8rdU","de":"Xemn177ZDck","tr":"p7tlsurxCg8","bn":"52yCNNcJUWw"},"shape":"tall","alt":"A pot of bouillabaisse fish soup with prawns, saffron broth and herbs","desc":"From France, bouillabaisse from Marseille, a saffron fish soup with mixed seafood and rouille on toast.","intro":"Bouillabaisse comes from Marseille, where fishermen made soup from the fish that did not sell, and it is now one of France's most loved celebration dishes. The broth is the star, built from fish stock, tomatoes, fennel, orange peel, saffron and olive oil, and the fish and shellfish cook in it for only a few minutes, so they stay tender. Serve it in two parts if you can, broth strained into bowls and fish on a platter, with rouille, a saffron garlic mayonnaise, spread on toasted bread. It sounds grand, but the method is simple, make a good broth, add the fish in the right order, and do not overcook it.","ing":["Mixed firm white fish 800g, cut into chunks","Prawns 300g, mussels 300g, cleaned","Fish stock 1.5 litres","Tomatoes 400g, chopped, tomato paste 2 tbsp","Fennel 1 bulb, onion 1, leek 1","Saffron 1 large pinch, orange peel 1 strip","Garlic 4 cloves, olive oil 4 tbsp, thyme","Crusty bread, rouille, parsley and lemon to serve"],"steps":["Heat olive oil in a large pot, fry the onion, leek, fennel and garlic for 8 minutes until soft and sweet.","Add the tomato paste and chopped tomatoes, and cook for 5 minutes until the tomatoes start to break down.","Pour in the fish stock, add saffron, orange peel, thyme and a pinch of salt, and simmer for 20 minutes.","Strain the broth through a sieve, pressing the vegetables to get all the flavour, then return the broth to the pot.","Bring the broth back to a gentle simmer, and add the firmest fish first, cooking for 3 minutes."],"tip":"Do not overcook the fish. Add the firmest pieces first and the delicate pieces last, and take the pot off the heat as soon as the fish flakes.","published":"2026-10-28"},{"id":"paella","name":"Seafood Paella","cat":"world","catLabel":"World Food","country":"Spain","veg":"nonveg","time":55,"diff":"Medium","servings":"6 people","img":"assets/seafood-paella-c85cf84d.webp","video":"LEAigDgpAIQ","videos":{"en":"LEAigDgpAIQ","ru":"EF27ohZ_a_Q","hi":"ZyrhMjMfeCE","es":"2Lm1wXk2jJ0","fr":"53q7baA0M40","ar":"Gy08501VHM0","pt":"dh37FUZgcus","rus":"jlysyUxFSps","zh":"tsMCNBwhleA","ja":"05gMwBN_0lU","de":"iocO5l_t87E","tr":"NVxo3nvRyJ0","bn":"QBoIDb6S37w"},"shape":"wide","alt":"Seafood paella in a wide pan with prawns, mussels, lemon and saffron rice","desc":"From Spain, seafood paella with saffron rice, prawns and mussels, and the crisp socarrat at the bottom.","intro":"Paella comes from Valencia in Spain, where it is cooked outdoors in a wide shallow pan, and the rice, not the seafood, is the real star. Saffron gives it the golden colour, a good stock gives it flavour, and the last few minutes of cooking, left undisturbed, create socarrat, the crisp toasted layer of rice at the bottom that everyone fights over. Use short grain bomba rice if you can, spread it in an even layer, and resist stirring once the stock goes in. Serve it in the pan, in the middle of the table, with lemon wedges, and let everyone dig in together.","ing":["Bomba or short grain rice 400g","Prawns 300g, mussels 300g, cleaned","Squid rings 200g, optional","Chicken or fish stock 1 litre, hot","Saffron 1 large pinch","Onion 1, red pepper 1, garlic 3 cloves","Tomatoes 2, grated, smoked paprika 1 tsp","Olive oil 4 tbsp, lemon 1, peas 100g"],"steps":["Soak the saffron in 3 tbsp of hot stock for 10 minutes, and keep the rest of the stock hot.","Heat olive oil in a wide paella pan, fry the onion and pepper for 6 minutes until soft, then add garlic and paprika.","Add the grated tomato and cook for 4 minutes until it darkens and thickens.","Add the rice and stir for 1 minute to coat it in the sofrito, then spread it in an even layer.","Pour in the hot stock and the saffron liquid, season with salt, and bring to a gentle boil. Do not stir from this point."],"tip":"Do not stir the rice after the stock goes in. Stirring releases starch and makes the rice sticky, and it stops the socarrat forming.","published":"2026-10-28"},{"id":"beefpho","name":"Beef Pho","cat":"world","catLabel":"World Food","country":"Vietnam","veg":"nonveg","time":180,"diff":"Hard","servings":"6 people","img":"assets/beef-pho-95032754.webp","video":"Tu-tQo93CCg","videos":{"en":"Tu-tQo93CCg","ru":"s-MvrV-7Z7A","hi":"VPYx_dsOLAM","es":"fry_E_96GyM","fr":"Hj9wK3gIZkY","ar":"3g8M4ZKSzjs","pt":"60rfwIqHNbQ","rus":"V8GsOq74yHk","zh":"SzliptZBU04","ja":"B-6qy_aAb8I","de":"Z8HsVqdUpk8","tr":"38hVFKIEIgs","bn":"6kX3ijtzINY"},"shape":"tall","alt":"A bowl of beef pho with rice noodles, sliced beef, herbs and bean sprouts","desc":"From Vietnam, beef pho with a clear spiced broth, rice noodles, thin sliced beef and fresh herbs.","intro":"Pho is Vietnam's most famous soup, and its heart is a clear broth that tastes of charred onion and ginger, star anise, cinnamon, cloves and fish sauce, simmered gently with beef bones until it is rich but never cloudy. The noodles cook separately, the beef is sliced paper thin and cooks in the hot broth as it is poured over, and the bowl is finished at the table with bean sprouts, Thai basil, coriander, lime and chilli. It takes time, but the work is mostly waiting and skimming, and the result is a bowl that is light, fragrant and deeply comforting, nothing like a heavy stew.","ing":["Beef bones 1.5kg, marrow or knuckle bones","Beef brisket or shin 500g","Rice noodles 500g, flat","Onion 2, ginger 1 large piece","Star anise 3, cinnamon stick 1, cloves 4","Coriander seeds 1 tsp, fennel seeds 1 tsp","Fish sauce 4 tbsp, rock sugar 1 tbsp","Bean sprouts, Thai basil, coriander, lime, chilli to serve"],"steps":["Blanch the bones in boiling water for 5 minutes, drain, rinse, and return them to a clean pot with fresh cold water.","Char the onion halves and ginger over an open flame or under a hot grill until blackened in patches, then add to the pot.","Toast the star anise, cinnamon, cloves, coriander and fennel in a dry pan for 2 minutes until fragrant, tie in muslin or add loose and strain later.","Simmer the broth very gently for 2 and a half hours, skimming often, and add the brisket for the last 60 minutes until tender.","Lift out the brisket, cool slightly, slice thinly, and strain the broth through a fine sieve until clear."],"tip":"Keep the simmer gentle and skim often. A rolling boil makes the broth cloudy and greasy, while a quiet simmer keeps it clear and clean tasting.","published":"2026-10-28"},{"id":"poutine","name":"Poutine","cat":"world","catLabel":"World Food","country":"Canada","veg":"nonveg","time":45,"diff":"Easy","servings":"4 people","img":"assets/poutine-ba527eac.webp","videos":{"en":"8cVLpvKeL-g","ru":"zVldz_FIUWc","hi":"oqXKjb2oJoA","es":"bKbNEEy7zds","fr":"-2cQ9f6YYpw","ar":"Trlw9Z0R1UM","pt":"9CNfVQGo35A","rus":"RfVSwniHRTo","zh":"olGThkKIGAA","ja":"c_K5_NBwm5U","de":"T1Re_8UHOxQ","tr":"J6At2uS_1CQ","bn":"KgHoLTLY3GA"},"shape":"wide","alt":"Poutine, fries topped with cheese curds and hot brown gravy","desc":"From Canada, poutine with crisp fries, squeaky cheese curds and hot beef or vegetable gravy.","intro":"Poutine comes from Quebec in Canada, and it is gloriously simple, hot crisp fries, fresh cheese curds that squeak when you bite them, and a rich brown gravy poured over the top so the curds just start to melt. The fries must be crisp enough to hold the gravy without going soggy in a minute, so double frying is worth it, and the gravy must be piping hot, because it is the heat that softens the curds. Serve it at once, in a bowl, with a fork, and eat it while the fries are still crisp at the edges and the gravy is pooling at the bottom.","ing":["Potatoes 1kg, floury variety","Cheese curds 250g, at room temperature","Beef or vegetable stock 500ml","Butter 2 tbsp, flour 2 tbsp","Soy sauce 1 tsp, Worcestershire sauce 1 tsp","Garlic 1 clove, black pepper","Oil for deep frying, salt","Spring onions to serve, optional"],"steps":["Cut the potatoes into thick batons, soak in cold water for 30 minutes, then drain and dry very well.","Heat oil to 160C, fry the chips in batches for 5 to 6 minutes until pale and soft, then drain and rest for 10 minutes.","While the chips rest, melt butter in a pan, stir in the flour, and cook for 2 minutes until lightly golden.","Whisk in the hot stock a little at a time, then add soy, Worcestershire, garlic and pepper, and simmer for 5 minutes until smooth and glossy.","Heat the oil to 190C, and fry the chips again in batches for 2 to 3 minutes until deep golden and very crisp. Drain and salt at once."],"tip":"Use cheese curds at room temperature. Cold curds stay firm and do not soften, while room temperature curds go soft and squeaky under the hot gravy.","published":"2026-10-28"},{"id":"bobotie","name":"Bobotie","cat":"world","catLabel":"World Food","country":"South Africa","veg":"nonveg","time":75,"diff":"Medium","servings":"6 people","img":"assets/bobotie-e54f148e.webp","shape":"tall","alt":"Bobotie, a baked South African mince dish with an egg topping and bay leaves","desc":"From South Africa, bobotie with spiced mince, fruit and a golden egg topping, served with yellow rice.","intro":"Bobotie is South Africa's beloved baked mince dish, with roots in Cape Malay cooking, where spiced mince is sweetened with fruit, enriched with soaked bread, and baked under a golden egg custard topping with bay leaves. The flavour is warm and gently sweet, curry powder, turmeric, chutney, raisins and apricot all working together, and the texture is soft and comforting, somewhere between a savoury bake and a light meatloaf. Serve it with yellow rice, chutney and a simple salad, and let the sweet and savoury balance do the talking. It is an ideal make ahead dish for a crowd, because it reheats beautifully and tastes even better the next day.","ing":["Beef or lamb mince 750g","Onion 1, garlic 2 cloves, ginger 1 tsp","Curry powder 2 tbsp, turmeric 1 tsp","White bread 2 slices, milk 250ml","Eggs 3, bay leaves 4","Chutney 3 tbsp, raisins 3 tbsp","Dried apricots 4, chopped, lemon juice 1 tbsp","Almonds 2 tbsp, flaked, salt and pepper"],"steps":["Soak the bread in 125ml of the milk until soft, then squeeze out the excess milk and crumble the bread.","Fry the onion, garlic and ginger in oil for 5 minutes until soft, then add the curry powder and turmeric and fry for 1 minute.","Add the mince and fry, breaking it up, until browned all over and the liquid has cooked off.","Stir in the soaked bread, chutney, raisins, apricots, lemon juice and seasoning, and cook for 5 minutes. Taste and adjust the sweet and sour balance.","Spoon the mince into a buttered baking dish, press it down evenly, and tuck the bay leaves into the top."],"tip":"Taste the mince before baking. The sweet, sour and spicy balance must be right at this stage, because baking will not fix it.","video":"8cOz0pp_YvQ","videos":{"en":"8cOz0pp_YvQ","ru":"RNpu4a70So0","hi":"5cB-c2Q2sOs","es":"KJM4g20bhqs","fr":"rI-N_f-ZkIg","ar":"o1kMVXZANwg","pt":"6ercJbx0cjM","rus":"tnoiqDPfjQo","zh":"g3fIcV4kF3A","ja":"9w6CyWsAFVQ","de":"68VyFTHenNk","tr":"wZZcWLQlm0o","bn":"wJDRDqVnCts"},"published":"2026-10-28"},{"id":"moussaka","name":"Moussaka","cat":"world","catLabel":"World Food","country":"Greece","veg":"nonveg","time":90,"diff":"Hard","servings":"6 people","img":"assets/moussaka-23654943.webp","videos":{"en":"rxZ3B3F4R_U","ru":"HQkknjxLcp4","hi":"2Bs6vVRg-xk","es":"MsXz-IJ1PFE","fr":"OGHJydQ2ei4","ar":"Sp35_Xjlyuk","pt":"0FFiRplDe2s","rus":"OOlnt3P1Gas","zh":"8TbFgH4hgVE","ja":"8Ol3LL1uAgI","de":"jQvdBeylj5o","tr":"Bhp61O3ZLcE","bn":"JXIUcIJHqQk"},"shape":"square","alt":"A slice of Greek moussaka with layers of aubergine, mince and bechamel","desc":"From Greece, moussaka with layers of aubergine, spiced mince and a thick golden bechamel top.","intro":"Moussaka is Greece's great layered bake, soft aubergine, a rich tomato and lamb or beef mince sauce scented with cinnamon, and a thick bechamel top that turns golden in the oven. It takes a little time, because each layer is cooked separately before the dish is assembled, but that is what gives it its structure and flavour, and it is best made ahead and rested, so the layers set and slice cleanly. Serve it warm, in squares, with a simple salad, and do not rush the resting time. It is a Sunday dish, generous and comforting, and it feeds a table happily.","ing":["Aubergines 2 large, sliced","Potatoes 3, sliced, optional","Lamb or beef mince 600g","Onion 1, garlic 3 cloves","Tomatoes 400g, chopped, tomato paste 2 tbsp","Cinnamon 1 tsp, oregano 1 tsp, nutmeg","Milk 500ml, butter 50g, flour 50g, eggs 2","Cheese 80g, grated, kefalotyri or parmesan"],"steps":["Salt the aubergine slices and rest for 30 minutes, then pat dry and fry or roast until golden and tender. Set aside.","Boil or roast the potato slices until just tender, if using, and set aside.","Fry the onion and garlic until soft, add the mince, and brown well, breaking it up.","Add the tomato paste, chopped tomatoes, cinnamon, oregano and seasoning, and simmer for 20 minutes until thick.","Make the bechamel by melting butter, stirring in flour, and whisking in warm milk until thick and smooth. Cool slightly, then whisk in the eggs and half the cheese."],"tip":"Rest the moussaka before cutting. Hot from the oven it falls apart, rested it slices into clean, beautiful layers.","published":"2026-10-28"},{"id":"hummus","name":"Hummus","cat":"world","catLabel":"World Food","country":"Middle East","veg":"veg","time":20,"diff":"Easy","servings":"6 people","img":"assets/hummus-7690ed83.webp","video":"FTAWJUZFkRw","videos":{"en":"FTAWJUZFkRw","ru":"t7SHt23lpN4","hi":"BoYdSKByHKQ","es":"2FL_SugMWpE","fr":"fdJVf6watfw","ar":"Eav8YO28giY","pt":"oGo3skV1MQw","rus":"wl2VlRpZM4Y","zh":"5TQczUii6X4","ja":"8XCOynLcRoE","de":"kJpakFqYc9k","tr":"vXe9kCPwNk4","bn":"NNZvNo4K_ZU"},"shape":"tall","alt":"A bowl of smooth hummus with olive oil, chickpeas and herbs","desc":"From the Middle East, silky smooth hummus with tahini, lemon and garlic, served with warm pitta.","intro":"Good hummus is all about texture, silky, light and whipped, never grainy or heavy. It comes from the Levant, where chickpeas, tahini, lemon and garlic are blended with ice water until the dip turns pale and fluffy, then finished with olive oil, paprika and whole chickpeas. The secret is to blend the tahini first, on its own, until it is completely smooth, and to use warm chickpeas, or chickpeas with their skins rubbed off, for the smoothest result. Serve it as part of a mezze spread, with warm pitta, olives and salad, and let everyone scoop and share.","ing":["Chickpeas 400g, cooked, drained","Tahini 120g, well stirred","Lemon juice 3 tbsp, garlic 1 small clove","Ice water 4 to 6 tbsp","Olive oil 2 tbsp, plus more to serve","Salt 1 tsp, cumin 1/2 tsp, optional","Paprika and parsley to serve","Warm pitta bread to serve"],"steps":["If using tinned chickpeas, warm them in their liquid for 5 minutes, drain, and keep a little liquid. Rub off loose skins if you have time.","Blend the tahini, lemon juice, garlic and salt for 2 minutes until very smooth, pale and slightly fluffy.","Add the warm chickpeas and blend for 3 to 4 minutes, scraping down the sides, until completely smooth.","Add ice water a tablespoon at a time, blending after each, until the hummus is light, whipped and soft enough to scoop.","Taste and adjust the lemon, salt and garlic. It should be bright and savoury, with tahini flavour, not sharp."],"tip":"Blend the tahini first, before the chickpeas. Tahini blended alone turns pale and creamy, and that is what makes the hummus silky.","published":"2026-10-28"},{"id":"falafel","name":"Falafel","cat":"world","catLabel":"World Food","country":"Middle East","veg":"veg","time":40,"diff":"Medium","servings":"4 people","img":"assets/falafel-d3905990.webp","videos":{"en":"4Xr9oOJjLjc","ru":"O6qkuMk5YBU","hi":"XKgVsm27-u4","es":"Qry_QMErFys","fr":"IlOZ5GTDK8k","ar":"8u5gKygm9k0","pt":"fzDJykl4iWs","rus":"YVqhJgHYP6k","zh":"BBICOBAN4YU","ja":"Ib0P5V6tYkQ","de":"9xML6ubi7oE","tr":"vvnklhvyhBw","bn":"yTT8gPRllXA"},"shape":"tall","alt":"Falafel balls with salad, pitta, tahini sauce and herbs","desc":"From the Middle East, crisp falafel made from soaked chickpeas, herbs and spices, with tahini sauce.","intro":"Real falafel is made from raw soaked chickpeas, never tinned or cooked chickpeas, and that is what gives it a light, fluffy inside and a crisp, craggy crust. The chickpeas are ground coarse with onion, garlic, parsley, coriander and cumin, rested so the mixture holds together, then shaped and fried until deep golden. Serve them in warm pitta with salad and tahini sauce, or as part of a mezze spread with hummus. The mixture can be made ahead and chilled, and the falafel fry in minutes, so they are perfect for a crowd, as long as you do not crowd the pan.","ing":["Dried chickpeas 250g, soaked overnight","Onion 1, garlic 3 cloves","Parsley 1 large bunch, coriander 1 bunch","Cumin 2 tsp, coriander powder 1 tsp","Baking powder 1/2 tsp, flour 2 tbsp","Salt 1 tsp, black pepper, chilli flakes","Oil for frying","Pitta, salad and tahini sauce to serve"],"steps":["Soak the chickpeas in plenty of cold water overnight, then drain very well. Do not cook them.","Put the chickpeas, onion, garlic, herbs, spices, salt and pepper in a food processor, and pulse until coarse and crumbly, not a paste.","Transfer to a bowl, stir in the flour and baking powder, cover, and refrigerate for 30 minutes to firm up.","Test one falafel first, shape a small ball, fry it, and check that it holds together and is cooked through.","Shape the rest into small balls or patties, about the size of a walnut, with wet hands."],"tip":"Use raw soaked chickpeas, never cooked chickpeas. Cooked chickpeas make a soft, mushy falafel that falls apart in the oil.","published":"2026-10-28"},{"id":"feijoada","name":"Feijoada","cat":"world","catLabel":"World Food","country":"Brazil","veg":"nonveg","time":180,"diff":"Hard","servings":"8 people","img":"assets/feijoada-bb4f21f2.webp","videos":{"en":"mUKDVyG_4aY","ru":"HF0PAUiyweo","hi":"s4kQ6xfjbH0","es":"0rKNZRkwGrw","fr":"uIXNyP0Td-I","ar":"hw6LHpD1mTU","pt":"tknZkmdoVIo","rus":"4o30GHeWQc0","zh":"czymJ7WPRn0","ja":"ARMMCcZF6ME","de":"Vdgl4dqH-Lw","tr":"_mlk87FOxec","bn":"zwQg6afdnc4"},"shape":"tall","alt":"Feijoada, Brazilian black bean stew with pork in a clay pot","desc":"From Brazil, feijoada with black beans and mixed pork, served with rice, collard greens and orange.","intro":"Feijoada is Brazil's national dish, a rich black bean stew with a mix of pork, sausage and smoked meats, cooked slowly until the beans are creamy and the meats are tender. It is traditionally served on Saturdays, as a long family lunch, with white rice, sauteed collard greens, farofa, toasted cassava flour, and orange slices to cut the richness. It takes time, and it feeds a crowd, so cook a big pot, keep the accompaniments simple, and let the meal stretch out. Soak the beans overnight, brown the meats well, and give the pot a long, gentle simmer, and the result is deeply satisfying.","ing":["Dried black beans 500g, soaked overnight","Pork shoulder 500g, cubed","Smoked sausage 300g, sliced","Bacon or salt pork 200g, diced","Onion 1, garlic 4 cloves","Bay leaves 3, cumin 1 tsp, oregano 1 tsp","Orange 1, for serving, rice and collard greens","Farofa or toasted breadcrumbs to serve, optional"],"steps":["Soak the beans overnight in cold water, drain, and rinse.","Brown the pork, sausage and bacon in batches in a large pot, then set aside, keeping the fat in the pot.","Fry the onion and garlic in the same pot until soft, then add the cumin and oregano.","Return the meats to the pot, add the beans, bay leaves and enough water to cover by 3cm.","Bring to a boil, skim, then reduce to a very gentle simmer, partly covered, for 2 to 2 and a half hours."],"tip":"Soak the beans overnight and simmer gently. Rushed beans stay hard, and a hard boil breaks them into mush instead of creamy beans.","published":"2026-10-28"},{"id":"meatpie","name":"Aussie Meat Pie","cat":"world","catLabel":"World Food","country":"Australia","veg":"nonveg","time":90,"diff":"Medium","servings":"6 people","img":"assets/aussie-meat-pie-e0439b27.webp","videos":{"en":"wFxrdTjKnpk","ru":"ve3EGUh0BXM","hi":"zJSBMtQ3o-s","es":"0pVf1zv3XjE","fr":"asFL7NhCHFQ","ar":"djI6dRPw67w","pt":"GKnS9QrkmKU","rus":"c7p8vtQbbfY","zh":"AVyQfJANCV4","ja":"tVj7erKY-dY","de":"yiWn02e_mOQ","tr":"oxBmM21RyL0","bn":"eXnCJsz12hg"},"shape":"tall","alt":"An Australian meat pie with golden pastry, cut open to show beef filling","desc":"From Australia, the classic meat pie with rich beef filling in crisp golden pastry, served with tomato sauce.","intro":"The Aussie meat pie is an icon, handheld, golden and eaten at football games, bakeries and kitchen tables all over Australia. Inside a crisp shortcrust base and a flaky puff pastry lid is a rich beef filling, slow cooked with onion, tomato, Worcestershire sauce and a little Vegemite for depth, thick enough to hold its shape when the pie is cut, but juicy enough to need tomato sauce on top. Make the filling ahead and cool it fully, because warm filling melts the pastry, then bake until the lid is deep golden. Serve it hot, with tomato sauce, and eat it with your hands, the Australian way.","ing":["Beef chuck 700g, diced small","Onion 1, garlic 2 cloves","Tomato paste 2 tbsp, beef stock 400ml","Worcestershire sauce 2 tbsp, Vegemite 1 tsp","Flour 2 tbsp, thyme 1 tsp","Shortcrust pastry for bases, puff pastry for lids","Egg 1, beaten, for glazing","Tomato sauce to serve, salt and pepper"],"steps":["Brown the beef in batches in a hot pot, then set aside. Brown the onion and garlic in the same pot.","Add the tomato paste and flour, cook for 1 minute, then pour in the stock, stirring to lift the browned flavour.","Return the beef, add Worcestershire, Vegemite and thyme, and simmer gently for 60 to 75 minutes until tender and thick.","Cool the filling completely, in the fridge if possible. Warm filling will melt the pastry and make it soggy.","Line greased pie tins or a muffin tin with shortcrust pastry, fill with the cold beef mixture, and brush the edges with egg."],"tip":"Cool the filling completely before filling the pastry. Even slightly warm filling softens the pastry and stops it crisping in the oven.","published":"2026-10-28"},{"id":"haleem","country":"Pakistan","name":"Haleem","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":270,"diff":"Hard","servings":"8 people","img":"assets/haleem-8bea0d50.webp","video":"AHHrKV57s8w","videos":{"en":"AHHrKV57s8w","ru":"-AXBuWZOTyQ","hi":"VhLkU-IsXb4","es":"x6knj3JrtQw","fr":"24OmGv23YFY","ar":"1Yxz4jOZqO4","pt":"ZvqQhIXMeVQ","rus":"csa5c7M1ErY","zh":"UQl48RGZwWI","ja":"utbE8t3YFXw","de":"B0UCXsUaxnE","tr":"GM6xJqPp-hU","bn":"LqERu8XgFSU"},"shape":"tall","alt":"A bowl of Pakistani haleem topped with fried onions, ginger, green chillies, coriander and lemon","desc":"Slow-cooked Pakistani haleem, beef, wheat and lentils mashed into a thick, silky porridge, served with fried onions and lemon.","intro":"Haleem is not fast food, it is food of patience. Wheat, barley and lentils soak overnight, beef cooks until it shreds, and everything is mashed together until the pot turns into one thick, silky porridge with the famous stringy texture.","ing":["Whole wheat berries (gandum) 1 cup, soaked overnight","Barley (jau) ½ cup, soaked overnight","Chana daal ½ cup, masoor daal ¼ cup, moong daal ¼ cup, mash daal ¼ cup","Beef 1 kg, beef bones 250 g","Ghee or oil 1 cup, onions 2 large, thinly sliced","Ginger paste 2 tbsp, garlic paste 2 tbsp, yoghurt 1 cup (whisked)","Red chilli powder 2 tbsp, Kashmiri chilli powder 1 tbsp, coriander powder 1½ tbsp, turmeric powder 1 tsp","Haleem masala 2 tbsp, salt 2 tbsp","Cumin seeds 1 tbsp, black peppercorns 1 tsp, cloves 6 to 8, green cardamom 5, black cardamom 2, cinnamon sticks 2, mace 2 blades, nutmeg ¼ piece, star anise 1","Ghee ½ cup, onion 1 medium, thinly sliced, for the tarka","Ginger 2 tbsp (julienned), fresh coriander ½ cup (chopped), fresh mint ½ cup (chopped), green chillies 4, lemons 3, for garnish","Chaat masala, for dusting"],"steps":["Soak the wheat, barley and lentils overnight, then cook them in water until completely soft and mushy.","Roast the whole spices and grind them into a fine powder.","Fry the onions in ghee, add ginger-garlic and the beef, then cook with the spices and yoghurt until the meat is falling-apart tender.","Shred the meat by hand, blend the grains lightly, and combine everything.","Mash and stir on low heat for 30 to 45 minutes, then pour over the hot ghee tarka and serve with naan and garnish."],"tip":"Soak the wheat and barley overnight, and mash the meat by hand. A food processor cuts the fibres too short and ruins the stringy texture.","published":"2026-10-31"},{"id":"chicken-korma","country":"Pakistan","name":"Chicken Korma","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":60,"diff":"Medium","servings":"4 people","img":"assets/chicken-korma-1579f580.webp","video":"Kiq7DDgnU-w","videos":{"en":"Kiq7DDgnU-w","ru":"M256OFbW85s","hi":"Bg_EA8PSahQ","es":"XmHG-QQAcSQ","fr":"rPvE3COJezY","ar":"Awu8z3G3djQ","pt":"0NijpEvpeOA","rus":"S788i7gWlR4","zh":"SNuYNSk_fYk","ja":"ph9HAmKyBqE","de":"pmWOgcqTmJw","tr":"wRCcpfZkSds","bn":"N29yIo48mp8"},"shape":"tall","alt":"A bowl of Pakistani chicken korma in a reddish-brown yoghurt gravy, garnished with julienned ginger and sliced almonds","desc":"Mild Pakistani chicken korma, bone-in chicken braised in yoghurt and crisp fried onions, with warm whole spices, served with naan.","intro":"Chicken korma is the great celebration curry of Pakistan, served at weddings, Eid dinners and dawaats with sheermal or hot naan. Bone-in chicken is marinated in yoghurt and spices, then braised gently until tender, while crisp fried onions blended with yoghurt give the gravy its famous reddish-brown colour and silky body — no tomatoes, no cream.","ing":["Chicken 1 kg, bone-in, skinless, cut into 8 to 10 pieces","Onions 3 medium, thinly sliced","Yoghurt 1 cup, full-fat, whisked (½ cup for the marinade, ½ cup for the onion paste)","Ginger-garlic paste 3 tsp (1 tbsp)","Coriander powder 3 tsp (1 tbsp), red chilli powder 1 tsp, turmeric powder ½ tsp, salt 1½ tsp","Oil or ghee ½ cup","Bay leaves 3, green cardamom 6, black cardamom 2, cloves 7, cinnamon sticks 2","Cumin seeds 1½ tsp, nutmeg ¼ piece, mace 2 blades, star anise ½","Kewra water 1 tsp","Fresh ginger 1-inch piece, julienned, for garnish","Sliced almonds ½ tbsp, for garnish (optional)","Water 2 cups"],"steps":["Grind the korma spices, mix the chicken with the ground spices and ½ cup of yoghurt, and marinate for 30 minutes.","Fry the onions until deep golden brown and crisp, then blend them smooth with the remaining ½ cup of yoghurt.","Fry the bay leaves and ginger-garlic paste in the same oil, add the marinated chicken with the ground spices and salt, and fry for 4 minutes.","Add 1 cup of water and cook covered on low to medium heat for 25 to 30 minutes until the chicken is tender.","Stir in the onion-yoghurt paste with 1 cup of water, cook on high heat until the oil separates, then finish with kewra water and ginger and serve with naan."],"tip":"Whisk the yoghurt until completely smooth and add it on low heat, stirring constantly. Cold or lumpy yoghurt in a very hot pot is the main reason korma splits.","published":"2026-11-01"},{"id":"aloo-paratha","country":"Pakistan","name":"Aloo Paratha","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":40,"diff":"Easy","servings":"4 people","img":"assets/aloo-paratha-b0b0a0b6.webp","video":"xahQzgAYGHE","videos":{"en":"xahQzgAYGHE","ru":"r2R7jcFWUcM","hi":"RCObCLEhm1c","es":"wH-I-pLL1tM","fr":"XLKbYDosFsA","ar":"D75i-ppdQQM","pt":"Qy8Gmx30tJQ","rus":"qJfOoK8eC7c","zh":"tiUtGXAHRPY","ja":"rMjB-Wke7YM","de":"6ZZgHMdGT_I","tr":"g8g3iyphCf8","bn":"cAFG0RuCtF0"},"shape":"tall","alt":"A stack of golden Punjabi aloo parathas on a plate with white butter, curd and pickle","desc":"Punjabi aloo paratha, whole wheat flatbread stuffed with spiced mashed potatoes, roasted golden on a tawa with ghee, served with butter, curd and pickle.","intro":"Aloo paratha is Punjab's favourite stuffed breakfast bread, a whole wheat flatbread filled with spiced mashed potatoes and roasted golden on a hot tawa with ghee. The dough is simple whole wheat flour, salt, oil and water, rested until soft, while boiled potatoes are mashed completely smooth with onion, green chillies, coriander, ginger and the classic spices of red chilli, cumin, garam masala and amchur — served hot off the tawa with white butter, curd and pickle.","ing":["Whole wheat flour (atta) 2 cups, plus extra for dusting","Salt 1 tsp (½ tsp for the dough, ½ tsp for the filling)","Oil 2 tbsp, for the dough","Water about ¾ cup, for kneading","Potatoes 3 medium, boiled, peeled and mashed","Onion 1 small, finely chopped","Green chillies 2, finely chopped","Fresh coriander leaves 2 tbsp, finely chopped","Ginger paste 1 tsp","Red chilli powder 1 tsp, cumin powder ½ tsp, garam masala ½ tsp, amchur (dry mango powder) ¾ tsp","Coriander seeds ½ tsp, ajwain (carom seeds) ¼ tsp","Ghee 2 tbsp, for roasting"],"steps":["Boil the potatoes until tender, peel and mash them completely smooth, then cool fully.","Mix the flour, ½ tsp salt and oil with water and knead into a soft dough; cover and rest for 30 minutes.","Mix the cooled mashed potatoes with the onion, chillies, coriander, ginger paste and spices, and divide into 4 balls.","Divide the dough into 4 balls, seal a ball of filling inside each disc of dough, and roll gently into a round paratha.","Roast on a hot tawa with ghee until golden-brown spots appear on both sides, and serve hot with white butter, curd and pickle."],"tip":"Mash the potatoes completely smooth and cool them fully before stuffing. Warm or lumpy mash is soft and wet, and it bursts through the dough while you roll.","published":"2026-11-02"},{"id":"kheer","country":"Pakistan","name":"Kheer","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":50,"diff":"Easy","servings":"6 people","img":"assets/kheer-8d799a64.webp","video":"3i0vBgrngXU","videos":{"en":"3i0vBgrngXU","ru":"rj5HCBmTB9g","hi":"QNSe9utO-yo","es":"7-cmmfwRoO0","fr":"kH_c3iG9F84","ar":"0FMrYog83Iw","pt":"qfOtzF2Iu2c","rus":"D_4fE_IAKAE","zh":"XGo1cU3Najc","ja":"O7NItj8FMbw","de":"uvOQq30ylUk","tr":"WVylUFmN0Wo","bn":"hM4hG_MejyM"},"shape":"tall","alt":"A bowl of creamy Pakistani kheer garnished with sliced pistachios, almonds and saffron strands","desc":"Pakistani kheer, creamy rice pudding of slow-cooked basmati rice in full-cream milk with cardamom, saffron and nuts, served warm or chilled.","intro":"Kheer is Pakistan's classic rice pudding — basmati rice slow-cooked in full-cream milk until thick and creamy, sweetened and scented with cardamom, saffron and rose water, and finished with almonds, cashews, pistachios and golden raisins. It is the dessert of Eid, weddings and family dinners, served warm or chilled in small bowls.","ing":["Basmati rice ¼ cup, rinsed and soaked for 20 minutes","Full-cream milk 1 litre","Sugar 6 tbsp","Green cardamom powder ½ tsp (or 5–6 green cardamom pods, crushed)","Saffron strands a generous pinch (14–16 strands), soaked in 1 tbsp warm milk","Almonds 1 tbsp, sliced","Cashews 1 tbsp, chopped","Pistachios 1 tbsp, sliced","Golden raisins 1 tbsp","Rose water 1 tbsp (optional)"],"steps":["Rinse and soak ¼ cup basmati rice for 20 minutes, then drain.","Bring 1 litre full-cream milk to a boil in a heavy pan on low heat, stirring often.","Add the drained rice and simmer on low heat until half cooked, then stir in 6 tbsp sugar.","Add cardamom, almonds, cashews, pistachios and saffron milk, and simmer until the rice is completely soft and the kheer is thick.","Stir in the raisins and rose water, pour into bowls and serve warm or chilled."],"tip":"Keep the heat low and stir often, scraping the sides of the pan. The milk solids that collect on the sides are the richest part — scrape them back in and the kheer turns silky instead of thin.","published":"2026-11-03"},{"id":"seekh-kebab","country":"Pakistan","name":"Seekh Kebab","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":65,"diff":"Medium","servings":"4 people","img":"assets/seekh-kebab-5b121cc5.webp","video":"tpq5UmgxWIU","videos":{"en":"tpq5UmgxWIU","ru":"ODOZPTHqJzA","hi":"4XcjKINGkC0","es":"rLE9c97rrb0","fr":"mDsAiP_Ktek","ar":"Af8DD55AIXM","pt":"sqvAG6ZEtJ0","rus":"B9Z1j7Z-oLI","zh":"ZcSb07UyXrs","ja":"i1PKDCeKaZc","de":"VHN_NMeRgwU","tr":"58MLA1HSAz0","bn":"jeWbLPFY7Uo"},"shape":"wide","alt":"Char-grilled Pakistani seekh kebabs on skewers with naan, sliced onions and green chutney","desc":"Pakistani seekh kebab, spiced minced lamb pressed onto skewers and char-grilled over glowing charcoal, served hot with naan, onions, lemon and mint chutney.","intro":"Seekh kebab is Pakistan's smoky char-grilled classic — minced lamb kneaded with onion, garlic, ginger, green chillies, coriander and mint, bound with gram flour and egg, pressed onto skewers and grilled over charcoal until charred outside and juicy inside. It is the barbecue centrepiece of Eid, weddings and family dinners, served hot with naan, sliced onions, lemon and mint chutney.","ing":["Lamb mince (or beef mince, 20% fat) 500g","Onion 1 medium, finely chopped","Garlic 4 cloves, minced","Ginger 2cm piece, grated","Green chillies 2, finely chopped","Fresh coriander leaves 30g, finely chopped","Fresh mint leaves 15g, finely chopped","Gram flour (besan) 2 tbsp","Cumin powder 2 tsp","Coriander powder 2 tsp","Garam masala 1 tsp","Red chilli powder 1 tsp","Turmeric powder 1/2 tsp","Salt 1 tsp","Egg 1, lightly beaten","Oil for brushing"],"steps":["Finely chop the onion, garlic, ginger, green chillies, coriander and mint.","Combine the mince with the chopped aromatics, gram flour, egg and all the spices, and knead well until the mixture binds.","Chill the mixture in the refrigerator for 30 minutes so the kebabs hold their shape.","With lightly oiled hands, press about 80-90g of mixture around each skewer into an even cylinder about 15cm long.","Grill over hot charcoal, turning often and brushing with oil, until charred outside and cooked through, about 10-12 minutes on charcoal (25 minutes in a 200C oven).","Rest the kebabs for 2 minutes, then slide them off the skewers onto a warm platter.","Sprinkle with a little chaat masala and chopped coriander.","Serve hot with naan, sliced onions, lemon wedges and mint chutney."],"tip":"Use mince with about 20% fat and squeeze the water out of the chopped onion — lean or wet mince makes kebabs that fall off the skewer. Chilling the mixture for 30 minutes is what keeps the kebabs firm on the skewer over the coals.","published":"2026-11-04"},{"id":"kabuli-pulao","country":"Afghanistan","name":"Kabuli Pulao","cat":"asian","catLabel":"Asian Dishes","veg":"nonveg","time":200,"diff":"Medium","servings":"6 people","img":"assets/kabuli-pulao-0730661f.webp","video":"rT1oLdvZm4c","videos":{"en":"rT1oLdvZm4c","ru":"ppl7B6-zWsk","hi":"VazkSm9TJao","es":"RgaAn8eGA6A","fr":"HC1d3iOpIBI","ar":"-lGDk0WUqz4","pt":"mRXvU1d4s18","rus":"t0wQssJXFKs","zh":"tfGttfzUtFo","ja":"SkLQb5M4-i8","de":"9wJCP-Tz2SU","tr":"sUO65FKec9w","bn":"8JOROK01Cvc"},"shape":"wide","alt":"A large dish of golden Afghan kabuli pulao topped with caramelised carrots, raisins, almonds and pistachios, with tender lamb","desc":"Afghanistan's national dish — golden basmati rice layered with tender spiced lamb, caramelised carrots, raisins, almonds and pistachios.","intro":"Kabuli Pulao is Afghanistan's national dish — golden basmati rice layered with tender, gently spiced lamb, topped with caramelised carrots and plump raisins, and finished with slivered almonds and pistachios. The rice gets its amber colour from caramelised sugar, not saffron, and the lamb is simmered until tender in its own stock, which then flavours the rice. It is the festive centrepiece of Afghan cooking, served at weddings and family gatherings, eaten from a shared dish, often with a floor spread called a dastarkhan.","ing":["Basmati rice 1 kg, rinsed and soaked in cold water for 2 hours","Lamb leg or shoulder, on the bone 800 g, chopped into 6 cm pieces","Vegetable oil 200 ml","Onion 1, chopped","Crushed garlic or garlic paste 1 tbsp","Salt 2 tbsp","White sugar 75 g (1/3 cup)","Garam masala 2 tsp (ground cloves, bay leaves, cardamom and cinnamon)","Freshly ground cardamom 1.5 tsp","Carrots 250 g, peeled and cut into batons","Sultanas or dried raisins 75 g","Mixed slivered almonds and pistachios 75 g, to garnish"],"steps":["Heat 50 ml of the oil in a large frying pan over medium heat and cook the onion for 6-8 minutes, until golden.","Add the lamb, garlic and 1 tbsp salt and cook for 8-10 minutes, until the lamb is well browned on all sides. Add water, reduce the heat to low and cook until the lamb is tender, skimming the froth off the surface occasionally. Remove the lamb and set aside; reserve the stock.","Place half of the sugar in a hot, dry saucepan over medium heat and cook, shaking the pan, for 5-6 minutes until the sugar has caramelised.","Carefully add 250 ml (1 cup) of reserved stock, salt, 1 tsp garam masala and a pinch of cardamom powder. Bring to the boil, then remove from the heat and set aside.","Drain the soaked rice and cook in a large saucepan of boiling water for 5 minutes, until only almost cooked. Drain and return to the pan.","Pour the caramelised sugar mixture over the rice, add a pinch of garam masala, and stir carefully and lightly until the rice is evenly coated and golden.","Heat 1 tbsp of the oil in a frying pan over medium-high heat. Add the carrot and the remaining sugar and stir for 5 minutes, until lightly caramelised and glossy. Add the sultanas and cook for another 1 minute, then stir in another pinch of cardamom and set aside.","Heat 1 tbsp oil in a frying pan until smoking and pour over the rice. Make holes through the rice with the end of a large spoon to let the steam through. Top with the spiced carrot and lamb pieces, cover and seal the pan with a tea towel, then a lid. Cook over high heat for 5 minutes, then reduce to low and cook for another 10 minutes. Remove from the heat and leave, covered, for 10 minutes. Serve layered: rice, then lamb, then remaining rice, topped with spiced carrots, almonds and pistachios."],"tip":"Do not rush the lamb: simmer it gently until it is truly tender, and keep the stock — it is what flavours the rice. Parboil the rice only until almost cooked; it finishes in the steam, and overcooked rice turns the pulao mushy.","published":"2026-11-04"},{"id":"dolma","country":"Armenia","name":"Dolma","cat":"world","catLabel":"World Dishes","veg":"nonveg","time":120,"diff":"Medium","servings":"6 people","img":"assets/dolma-bd7aa9c8.webp","video":"WsqbCwJMQ1E","videos":{"en":"WsqbCwJMQ1E","ru":"RpWNYSy2-uU","hi":"7b3SpTuTiq4","es":"igCvJczK0ds","fr":"ifTyySKeVk4","ar":"OBS4qGFfbXM","pt":"8luTSQTb_To","rus":"k2iB5bdRauc","zh":"YLe7B2xgau4","ja":"KmWH4zkeBbk","de":"IfA8zL85rUg","tr":"H4wR1uy7abA","bn":"t72DeU4XT3o"},"shape":"tall","alt":"A plate of glossy Armenian dolma, stuffed grape leaves arranged in a circle with lemon wedges and fresh herbs","desc":"Armenian dolma, tender grape leaves rolled around spiced minced lamb and rice, simmered in broth with lemon and tomato until tender, served warm with yoghurt.","intro":"Dolma is Armenia's classic stuffed grape leaf dish — tender vine leaves rolled around a filling of spiced minced lamb or beef, long-grain rice, onion, parsley, mint and garlic, seasoned with allspice, cinnamon and cumin, then packed snugly into a pot with lemon slices and simmered gently in broth until the rice is cooked and the leaves are tender. It is the dish of family gatherings and celebrations across Armenia, served warm with yoghurt or a cucumber and tomato salad.","ing":["Grape leaves 30-40 (1 jar, brined) or fresh leaves, blanched","Ground lamb or beef 500g (or a mix of both)","Long-grain rice 1 cup, rinsed","Onion 1 large, finely chopped","Fresh parsley 1/2 cup, finely chopped","Fresh mint 1/4 cup, finely chopped","Garlic 3-4 cloves, minced","Ground allspice 1 tsp","Ground cinnamon 1/2 tsp","Ground black pepper 1/4 tsp","Ground cumin 1/4 tsp","Tomato sauce or tomato paste 1/2 cup","Lemon 1, thinly sliced","Olive oil 2-3 tbsp","Salt 1 tsp, or to taste","Chicken or vegetable broth 3 cups"],"steps":["Rinse jarred grape leaves thoroughly under cold water to remove excess brine; if using fresh leaves, blanch in boiling water for 1-2 minutes, then cool in ice water and pat dry.","In a large bowl combine the minced meat, rinsed rice, chopped onion, parsley, mint, minced garlic, allspice, cinnamon, black pepper, cumin, 1 tbsp olive oil and 1/2 tsp salt, and mix thoroughly by hand.","Lay a grape leaf flat, vein-side up, trim the stem, and place 1-2 tbsp of filling at the centre near the base.","Fold the bottom edge over the filling, fold in the sides, and roll up tightly into a neat cylinder; repeat for all leaves and filling.","Line a large pot with a few damaged grape leaves or lemon slices, then arrange the rolled dolma snugly in layers, placing lemon slices between layers.","Mix the tomato sauce or paste with the remaining olive oil, salt and black pepper, and pour over the dolma; top with more lemon slices.","Pour in enough broth to cover the dolma, place a heat-proof plate or a few grape leaves on top to hold them down, bring to a boil, then cover and simmer on low for 1 to 1.5 hours until the rice is cooked and the leaves are tender.","Remove from the heat, rest briefly, and serve warm with yoghurt or a cucumber and tomato salad."],"tip":"Pack the rolls in snugly — if they have room to move they unravel while simmering. The plate on top is not optional; it keeps every roll tight and submerged so the rice cooks evenly.","published":"2026-11-04"},{"id":"plov","country":"Azerbaijan","name":"Plov","cat":"world","catLabel":"World Dishes","veg":"nonveg","time":90,"diff":"Medium","servings":"6 people","img":"assets/plov-c341c480.webp","video":"eAZhD_tYiBs","videos":{"en":"eAZhD_tYiBs","ru":"_0ERdOysMKk","hi":"akWADDjSqRU","es":"mxtGiC3gnqk","fr":"Evtaj1JthmE","ar":"Kh9XCmPjpss","pt":"XQgnGIRmoZ0","rus":"9Gv0jgFPIAA","zh":"WpWC5QzFiww","ja":"cwcgbvr4ZU8","de":"N5pKR9Uw57M","tr":"LSUAYaW96dw","bn":"H4Ul8VbELPc"},"shape":"tall","alt":"A large platter of golden Azerbaijani plov, saffron rice with tender lamb, chestnuts, dried apricots and raisins, garnished with fresh herbs","desc":"Azerbaijan's national dish, golden saffron basmati rice layered with tender lamb, chestnuts and dried fruits, steamed until fluffy and served on a large platter.","intro":"Plov is Azerbaijan's national dish — golden saffron basmati rice layered with tender lamb, chestnuts and dried fruits, steamed slowly in one pot until the grains are separate and fluffy. The rice and the lamb-and-fruit filling are cooked separately, then layered and steamed together, and the dish is served on a large platter with pickles, salad or fresh herbs. It is the centrepiece of weddings, Novruz and every celebration in Azerbaijan.","ing":["Basmati rice 3 cups, rinsed and soaked in salted water for 30 minutes","Lamb 700 g, boneless, cut into cubes","Chestnuts 1 cup, peeled","Dried apricots 1/2 cup, pitted","Dried sour plums 1 cup, pitted","Pitted dates 1/2 cup","Golden raisins 1/2 cup","Butter 4 tbsp","Onion 1 medium, sliced in half-circles","Saffron 1/3 tsp ground threads, dissolved in 3 tbsp hot water","Salt 1 tbsp for soaking + 2 tbsp for boiling + 1/2 tsp for seasoning","Ground black pepper to taste"],"steps":["Rinse 3 cups basmati rice until the water runs clear, then soak in lukewarm water with 1 tbsp salt for 30 minutes.","Heat 2 tbsp butter in a pan; fry 1 cup peeled chestnuts for 3 minutes, add 1/2 cup dried apricots, 1 cup sour plums and 1/2 cup dates and fry 3 more minutes, then add 1/2 cup golden raisins and fry 1 minute. Remove from heat.","Boil 10 cups water with 2 tbsp salt; add the drained rice in batches and boil 7-10 minutes until the grains surface and are barely done; drain.","Melt 1 tbsp butter in the pot; arrange 700 g lamb in one layer at the bottom, season with 1/2 tsp salt and pepper; layer 1 sliced onion on top; simmer uncovered for 3 minutes without stirring. (If using lamb, boil it first for 5 minutes, skim the froth and drain.)","Layer half the rice over the onion, arrange the dried fruits and chestnuts on top, then pile the rest of the rice into a pyramid; pour 1 tbsp melted butter over.","Cover the pot with a clean towel and lid to trap the steam; cook on low heat for 30 minutes.","Open the lid and sprinkle 1/3 tsp saffron dissolved in 3 tbsp hot water over the rice; cover again and simmer for another 30 minutes until the rice is fluffy and separate and the meat is golden.","Serve on a large platter, scooping rice, fruits and lamb together, with pickles, salad or fresh herbs."],"tip":"Do not overcook the rice in the boiling step — it must be barely done when drained, because it finishes steaming in the pot. The towel under the lid absorbs the steam so the grains stay separate and fluffy instead of sticky.","published":"2026-11-04"},{"id":"machboos","country":"Bahrain","name":"Machboos","cat":"rice","catLabel":"Rice Dishes","veg":"nonveg","time":135,"diff":"Medium","servings":"6 people","img":"assets/machboos-fd440d36.webp","video":"ha-oTq-DEXk","videos":{"en":"ha-oTq-DEXk","ru":"bvniaOyyvnc","hi":"nfnuklh5Ku0","es":"y-mY1dExGIo","fr":"iEXmRWidcXA","ar":"1tOAMsWgf4E","pt":"5Iw6Yb3H1K0","rus":"eISu9cPPGhc","zh":"oCV6ppsoQqI","ja":"z7fLWh2ojH8","de":"IS_VyGa0nNI","tr":"Ye0-j7t56sY","bn":"2SzIPsS0x5k"},"shape":"tall","alt":"A large platter of Bahraini machboos, golden spiced basmati rice topped with grilled chicken, fried onions, raisins and nuts","desc":"Bahrain's national dish: tender chicken simmered with baharat, dried limes and tomatoes, served over fragrant basmati rice finished with rose water and lemon.","intro":"Machboos is Bahrain's national dish — tender chicken simmered in a fragrant stock of baharat, dried black limes, tomatoes, garlic and ginger, then served over golden basmati rice cooked in that same stock and finished with rose water, lemon juice and butter. It is the Friday family feast of Bahrain, served on a large platter with the grilled chicken laid over the rice and scattered with fried onions, raisins and nuts. The dish takes its time — about an hour of gentle simmering for the chicken and a slow final steam for the rice — but most of that time is hands-off, and the result is a whole meal in one pot: spiced, tart, fragrant and deeply satisfying.","ing":["Chicken 1 to 1.5 kg, cut in half","Basmati rice 650 g, rinsed and soaked for 10 minutes","Water 4.5 cups","Tomatoes 3, quartered","Onions 3, finely chopped","Coriander leaves 1/4 cup, chopped","Green hot pepper 1","Black dried limes 2, pierced","Baharat spice mix 2 tsp","Turmeric powder 1.5 tsp","Cumin powder 1 tsp","Cinnamon 2 tsp","Cardamom powder 1 tsp","Garlic 2 cloves","Gingerroot 1 slice, cut into small pieces","Butter 3 tbsp","Lemon juice 1/4 cup","Rose water 3 tbsp","Oil 3 tbsp","Salt 3 tsp"],"steps":["Mix the baharat, turmeric, cumin and cardamom with 1 tsp salt, and sprinkle half of the spice mixture over the chicken halves.","Heat the oil in a large pot and fry the onions until golden brown, then add the green hot pepper and the pierced dried limes.","Add the chicken, coat it in the spices and cinnamon, cover and cook for 3 minutes, then add the garlic, ginger and tomatoes and cook for 3 more minutes.","Sprinkle in the remaining salt, pour in the hot water, cover and simmer for about 1 hour until the chicken is cooked through.","Remove the chicken, brush with oil, sprinkle with the remaining cinnamon and grill in the oven for 10 to 15 minutes until golden brown.","Add the drained rice to the chicken stock in the pot and cook on low heat for 20 to 25 minutes until it has absorbed the stock.","Sprinkle the rose water and lemon juice over the rice, place the butter pieces on top, cover and cook on low heat for 30 minutes.","Serve the rice on a large serving plate and place the grilled chicken halves on top, garnished with extra coriander and a lemon wedge."],"tip":"Pierce each dried lime before adding it to the pot, or its tart flavour stays locked inside. Keep the heat very low during the final 30 minutes of steaming so the rice turns fluffy and never sticks.","published":"2026-11-04"},{"id":"ilish-bhapa","country":"Bangladesh","name":"Ilish Bhapa","cat":"fish","catLabel":"Fish Dishes","veg":"nonveg","time":40,"diff":"Easy","servings":"4 people","img":"assets/ilish-bhapa-74cc4d65.webp","video":"1Liyja7k_Tg","videos":{"en":"1Liyja7k_Tg","ru":"c5R1tHGw6QU","hi":"99RABoCTTGE","es":"2wvrTDaGdSQ","fr":"H1Nymxangns","ar":"7GgJAkIKDuc","pt":"Hnk8c0RLXG0","rus":"MqOpOpYKxYE","zh":"K_5xa2W5awI","ja":"qTER4BcaDSY","de":"qWLPQTPBQIM","tr":"X_9EiMK8fXw","bn":"KZLNJCszJYQ"},"shape":"tall","alt":"Ilish Bhapa — Bangladeshi hilsa fish steamed in golden mustard paste with green chillies, served with steamed rice","desc":"Bangladeshi Ilish Bhapa, hilsa fish steamed in a pungent mustard, yoghurt and coconut paste with green chillies and mustard oil, served hot with steamed rice.","intro":"Ilish Bhapa is Bangladesh's beloved steamed hilsa — hilsa, the national fish of Bangladesh, steamed in a potent mustard, yoghurt and coconut paste with green chillies and mustard oil. The raw fish is never fried; it cooks gently in its own steam inside a sealed tiffin box, staying tender, juicy and soft, and the mustard paste turns golden and fragrant. It is the dish Bengalis serve to honoured guests, opened at the table to reveal the steaming fish, and eaten hot with plain steamed rice.","ing":["Hilsa fish (ilish machh) 250 g, 4 pieces cut 3 cm thick","Mustard seeds 40 g, brown and yellow mixed, soaked for 2 hours","Green chillies 8 pcs","Coconut 40 g, peeled and grated","Yoghurt 25 g, beaten","Salt 22 g (Bong Eats; cross-check recipes use about 1 tsp)","Sugar 1/4 tsp","Turmeric powder 1/2 tsp","Mustard oil 20 g"],"steps":["Clean the hilsa and cut it into 3-cm-thick slices.","Soak the mustard seeds in water for 2 hours. Strain, then grind with salt and 4 green chillies to a smooth paste.","Mix in the grated coconut, beaten yoghurt, sugar, turmeric and mustard oil.","Coat the fish pieces well with the mixture.","Arrange them in a tiffin box, with halved green chillies placed over the top.","Fasten the lid and set the fish aside to marinate for at least 15 minutes.","Place a stand in a pan, pour in hot water up to half the height of the tiffin box, and once the water boils set the tiffin on the stand. Cover the pan and steam on medium heat for 15 minutes.","Remove from the pan and allow it to rest for another 5 minutes before serving hot with steamed rice."],"tip":"Grind the mustard seeds only briefly — over-grinding makes mustard bitter. Pulse two or three times, scraping down the sides, until just smooth. And never fry the fish for this dish: raw hilsa steamed in the paste turns out tender, juicy and soft.","published":"2026-11-04"},{"id":"ema-datshi","country":"Bhutan","name":"Ema Datshi","cat":"asian","catLabel":"Asian Dishes","veg":"veg","time":25,"diff":"Easy","servings":"2 people","img":"assets/ema-datshi-4f140328.webp","video":"2FLIvTgJDbw","videos":{"en":"2FLIvTgJDbw","ru":"W4SKqeBbYog","hi":"OlBmoTxfdRY","es":"eZG8nBLJVXw","fr":"C5VY4Yc5ZTQ","ar":"F-nKZ8N_qvI","pt":"--Rz69WPQL8","rus":"zbKI1v0e5Bo","zh":"_T6SreFHCas","ja":"TD3PqyHvVRs","de":"_hucWbVkgGs","tr":"WcsQmmCJmFM","bn":"v0SG2cOIL78"},"shape":"tall","alt":"A bowl of Bhutanese Ema Datshi, green and red chillies in a creamy melted cheese sauce, served with red rice","desc":"Bhutan's national dish, a fiery stew of green and red chillies simmered with onion, tomato and garlic, then finished with melted cheese into a creamy sauce, served hot with red rice.","intro":"Ema Datshi is Bhutan's national dish — 'ema' means chilli and 'datshi' means cheese in Dzongkha. Chillies are treated as a vegetable, not a seasoning: 220 g of chillies are simmered with onion, tomato and garlic until soft, then the heat is switched off and grated cheese is stirred in until it melts into a creamy sauce that coats every chilli. It is served hot with boiled red rice, and it is eaten in Bhutanese homes almost every day.","ing":["Jalapeno chillies 220 g, quartered lengthwise","Green chillies 6 g, slit (2 small green chillies)","Onion 70 g, sliced","Garlic 15 g, roughly chopped (about 3 cloves)","Tomato 50 g, diced","Cheese 75 g, grated (datshi, or feta, mozzarella or farmers cheese)","Butter 15 g","Vegetable oil 7 g","Salt 5 g","Water 250 g (about 1 cup)"],"steps":["Remove the stalks from the chillies and cut them in quarters lengthwise. Slit the small green chillies, slice the onion, roughly chop the garlic, and dice the tomato.","Add all of these to a pan along with the salt, the vegetable oil and 250 g of water.","Cover the pan with a lid and boil on medium heat for 15 minutes, until the chillies have softened.","Turn off the heat and add the butter and the grated cheese. Turning the heat off before adding the cheese stops it from curdling.","Stir gently until the cheese has melted into a creamy sauce that coats the chillies.","Check the salt and adjust it — how much you need depends on how salty your cheese is.","Cook red rice separately while the stew simmers, and keep it hot.","Serve the Ema Datshi hot over a bed of boiled red rice."],"tip":"Turn the heat OFF before adding the cheese. Cheese added over direct heat curdles and goes grainy; stirred into the hot stew off the heat, it melts into a smooth, creamy sauce.","published":"2026-11-04"},{"id":"ambuyat","country":"Brunei Darussalam","name":"Ambuyat","cat":"asian","catLabel":"Asian Dishes","veg":"nonveg","time":25,"diff":"Easy","servings":"4 people","img":"assets/ambuyat-8c8ff153.webp","video":"cTs2bFkLELQ","videos":{"en":"cTs2bFkLELQ","ru":"K-Pw655unUM","hi":"oSBi8SNqsYg","es":"U-Q8ogFZoVE","fr":"lFuFPttcyOA","ar":"pqRIoXhf5_c","pt":"M2_72SyH-r8","rus":"tjotxDcp39g","zh":"hXnsb2SsVks","ja":"sC2l1m8pwKo","de":"AyHOj_YLqFY","tr":"ZfhMeS7zbtM","bn":"11Gw50_-rrg"},"shape":"tall","alt":"Glossy white Bruneian ambuyat sago starch wound around bamboo candas, served with a bowl of spicy red cacah dipping sauce","desc":"Brunei's national dish: sago palm starch stirred with boiling water until glossy, translucent and sticky, wound onto bamboo sticks and dipped in spicy cacah sauce.","intro":"Ambuyat is the national dish of Brunei Darussalam — sago palm starch mixed with water and stirred with boiling water until it turns into a glossy, translucent, glue-like mass. It is almost tasteless on its own, so it is wound onto bamboo sticks called candas and dipped into a fiery cacah sauce of chilies, shrimp paste and lime, and eaten with grilled prawns, fish and vegetables. It is swallowed without chewing, traditionally, and it is incomplete without at least three side dishes and dips to go with it.","ing":["Sago starch 1 cup (or tapioca starch as a substitute)","Cold water 1/2 cup","Boiling water 3 cups","Fresh red chilies 5-7, for the cacah","Bird's eye chilies 2-3 (optional, for extra heat)","Belacan (shrimp paste) 1 tbsp, toasted","Lime juice 2 tbsp (from 1-2 limes)","Shallot 1 small","Sugar 1/2 tsp","Salt 1/4 tsp"],"steps":["Put 1 cup sago starch in a heatproof bowl, add 1/2 cup cold water and stir well with a spoon or spatula until you have a smooth, lump-free paste. This step is crucial for preventing lumps later.","Bring 3 cups water to a rolling boil in a kettle or pot.","Slowly pour the boiling water into the sago paste in a thin stream while continuously stirring vigorously. The mixture will immediately begin to thicken and turn translucent.","Keep stirring until the entire mixture transforms into a thick, sticky, gelatinous mass. It should be mostly clear with a slight opalescent sheen.","Once fully transformed, let the ambuyat sit for 1-2 minutes. It will become even firmer. Transfer to a communal serving bowl and serve immediately while warm.","If your belacan is not already toasted, gently toast 1 tbsp in a dry pan over low heat for 1-2 minutes until fragrant. Be careful not to burn it.","Roughly chop the chilies and the shallot. In a mortar and pestle, or a small food processor, pound the toasted belacan, chilies, shallot, 1/2 tsp sugar and 1/4 tsp salt until you get a coarse paste.","Stir in 2 tbsp lime juice, taste and adjust the seasoning, and transfer the cacah to a small serving bowl. Wind a little ambuyat onto bamboo candas, dip it into the cacah, and eat it with grilled prawns, fish and vegetables."],"tip":"Mix the starch into a smooth paste with cold water first — this is the step that prevents lumps. Pour the boiling water in a thin stream and never stop stirring, or the starch sets in lumps instead of turning glossy and smooth.","published":"2026-11-04"},{"id":"fish-amok","country":"Cambodia","name":"Fish Amok","cat":"asian","catLabel":"Asian Dishes","veg":"nonveg","time":55,"diff":"Medium","servings":"4 people","img":"assets/fish-amok-671b6c63.webp","video":"Cbf0l05ROno","videos":{"en":"Cbf0l05ROno","ru":"ld4AKmcX7LQ","hi":"0TepCYGMdis","es":"gL8s7BT9ytM","fr":"wx1acldlfJM","ar":"mDeAUEhLv3E","pt":"6NRXb1SaKAI","rus":"kUU5YL_dwvw","zh":"84Uinncyd74","ja":"ClXc2iTqsYQ","de":"o0gBqIRSqWk","tr":"X2nxweTTC9s","bn":"kpGaBKVOfTQ"},"shape":"tall","alt":"Cambodian Fish Amok, golden coconut fish curry steamed in a banana leaf cup, garnished with kaffir lime leaves and red chilli","desc":"Cambodia's national dish — white fish steamed in banana leaf cups in a fragrant coconut curry with kroeung spice paste, set like a soft custard and served hot with rice.","intro":"Fish Amok, or Amok Trey, is Cambodia's national dish — white fish gently steamed in banana leaf cups in a fragrant coconut curry built on kroeung, the Khmer spice paste of lemongrass, galangal, turmeric, garlic, shallots and kaffir lime leaves. Eggs give the curry a soft, custard-like set, and the banana leaf adds a subtle earthy aroma. It is served hot, garnished with kaffir lime leaves and red chilli, with steamed rice.","ing":["White fish fillet 500 g (catfish, tilapia or snapper), cut into bite-sized pieces","Coconut milk 1 cup","Coconut cream 1/2 cup","Eggs 2, beaten","Kroeung paste 3 tbsp (2 stalks lemongrass, 2 shallots, 2 garlic cloves, 1 small piece galangal, 1 tsp fresh turmeric, 2 kaffir lime leaves, 1 tsp shrimp paste)","Fish sauce 1 1/2 tbsp","Palm sugar 1 tsp","Banana leaves 2-3, cut into squares (or small ramekins)","Red chilli 1, thinly sliced, and kaffir lime leaves, finely sliced, to garnish"],"steps":["Make the kroeung: pound the lemongrass, shallots, garlic, galangal, turmeric, kaffir lime leaves and shrimp paste into a smooth paste.","Whisk the coconut milk, coconut cream, 3 tbsp kroeung paste, fish sauce, palm sugar and beaten eggs until smooth.","Cut the fish into bite-sized pieces, fold into the coconut mixture and marinate for 15 minutes.","Soften the banana leaves over a flame or in hot water, then fold them into cups (or use small ramekins).","Spoon the fish mixture into the cups, filling them about three-quarters full.","Place the cups in a steamer over boiling water and steam for 20-25 minutes, until the curry is set and custard-like.","Spoon a little coconut cream over the top and steam for 2-3 minutes more.","Garnish with sliced kaffir lime leaves and red chilli, and serve hot with steamed rice."],"tip":"Do not overfill the banana leaf cups — three-quarters full leaves room for the mixture to set without spilling. The amok is done when it is firm to the touch but still moist, like a soft custard, never dry.","published":"2026-11-04"},{"id":"souvla","country":"Cyprus","name":"Souvla","cat":"grill","catLabel":"Grill & BBQ","veg":"nonveg","time":140,"diff":"Medium","servings":"3 people","img":"assets/souvla-b72e82d3.webp","video":"LFSFrIbJDTM","videos":{"en":"LFSFrIbJDTM","ru":"1KsrVkYz_Sk","hi":"wZVODPDARsE","es":"EYTRqWVnSec","fr":"nxWDhwGjSqI","ar":"Qmkbdm9Dec8","pt":"OLGXE5fWqS0","rus":"0ARenKYWs1c","zh":"ogyTZDAfGXI","ja":"wO8GeE3DrkU","de":"YY-GFm1uv8o","tr":"drXi_O_3YW8","bn":"m7HpuarY-pU"},"shape":"wide","alt":"Cypriot souvla — golden-brown charcoal-grilled pork skewers served with pita bread, salad and lemon","desc":"Cypriot souvla, large chunks of pork shoulder marinated in red wine, olive oil and Greek oregano, threaded onto skewers and slow-grilled over charcoal, served with lemon and warm pita bread.","intro":"Souvla is Cyprus's most famous dish — large chunks of pork shoulder marinated in red wine, olive oil, salt, pepper and Greek oregano, threaded onto long skewers and cooked slowly over glowing charcoal on a foukou grill. Unlike souvlaki, which uses small pieces cooked fast, souvla is browned first and then raised higher above the coals to cook low and slow for up to two hours, turning regularly, until the outside is crisp and golden and the inside is juicy and smoky. It is served with lemon wedges, warm pita bread and salad.","ing":["Pork shoulder 2.5 lb (about 1.1 kg), cut into cubes about 2.5 cm across","Red wine 2 tbsp (or good red wine vinegar)","Olive oil 2 tbsp","Sea salt 1 tbsp","Greek oregano (rigani) 1 tsp, ground","Freshly ground black pepper 0.5 tsp","Lemon 1, cut into wedges, to serve","Pita breads 6, to serve","Tahini dip, optional, to serve"],"steps":["Cut 2.5 lb pork shoulder into cubes about 2.5 cm across.","Pour 2 tbsp red wine and 2 tbsp olive oil over the pork in a bowl and toss to coat.","Sprinkle over 1 tbsp sea salt, 0.5 tsp black pepper and 1 tsp Greek oregano, and toss again.","Cover and refrigerate for at least 2 hours, ideally overnight.","Thread about 6 pieces of meat onto each skewer, making about 12 skewers.","Place the skewers on a hot charcoal grill and turn often until browned evenly on all sides, about 15 minutes.","Raise the skewers higher above the charcoal and grill slowly for 90 minutes to 2 hours, turning regularly.","Warm the pita breads over the grill, rest the meat briefly, squeeze lemon over it and serve with the warm pita."],"tip":"Do not rush souvla. Brown the skewers first for colour, then lift them higher above the coals and let the gentle heat do the work — that slow second stage is what makes the meat juicy inside and crisp outside.","published":"2026-11-04"},{"id":"mutton-pulao","country":"Pakistan","name":"Mutton Yakhni Pulao","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":75,"diff":"Medium","servings":"5 people","img":"assets/mutton-pulao-9f2b8a1c.webp","videos":{"en":"9g9AtwPxv04","ru":"fub-pQFj-Ns","hi":"5mQGhmpKNBk","es":"hyJfQoqhRA0","fr":"37h0AQPlQ8s","ar":"-z8O5t9GAOE","pt":"2QwGO9XLU5w","rus":"jtPq94uvYmU","zh":"CG0DbbgV2YM","ja":"s3NmVJTWhFo","de":"TafgMF2c7IM","tr":"lbySRAnNSAo","bn":"OQ47l5dYKXs"},"shape":"tall","alt":"Steaming Pakistani Mutton Yakhni Pulao in an earthenware platter with ZaikaWorlds logo","desc":"Fragrant long-grain basmati rice cooked gently in a deeply spiced slow-simmered bone-in mutton broth (yakhni) with caramelized onions and whole spices.","intro":"Mutton Yakhni Pulao is the pride of celebration dining across Pakistan and North India. Unlike intensely spiced biryani, authentic pulao derives its delicate yet profound flavour directly from the slow-extracted yakhni broth, infused with fennel seeds, coriander, ginger, garlic, and whole warm spices.","ing":["Bone-in mutton (shoulder or leg) 800 g","Aged basmati rice 3 cups, washed and soaked 30 mins","Fennel seeds (saunf) 2 tbsp, whole coriander seeds 2 tbsp","Onions 3 medium, thinly sliced","Ginger-garlic paste 2 tbsp, sliced ginger 1 tbsp","Whole spices: 2 bay leaves, 4 green cardamoms, 1 black cardamom, 1 cinnamon stick, 6 cloves","Plain yoghurt 1/2 cup, whisked","Ghee or cooking oil 1/2 cup","Salt to taste, green chillies 4 slit"],"steps":["Prepare the yakhni: In a deep stockpot, combine mutton pieces, 7 cups water, fennel seeds, coriander seeds, sliced ginger, garlic cloves, 1 sliced onion, and salt. Bring to a boil, skim the surface, cover and simmer on low heat for 50-60 minutes until the meat is tender.","Strain the broth through a fine mesh sieve into a bowl, discarding whole spice seeds. Reserve the tender mutton pieces and keep 5 cups of clear strained yakhni broth.","In a wide heavy-bottom pot, heat ghee and fry the remaining sliced onions until golden brown. Remove 1/3 of the onions for garnish.","Add ginger-garlic paste, whole spices (bay leaf, cardamoms, cinnamon, cloves), and whisked yoghurt into the pot. Sauté for 3 minutes until oil separates.","Add the boiled mutton pieces and green chillies. Fry gently for 4 minutes to coat the meat in aromatics.","Pour in the 5 cups of strained hot yakhni broth and bring it to a rolling boil. Taste and adjust salt.","Gently add the drained soaked basmati rice. Cook uncovered on medium-high heat until 85% of the liquid is absorbed and small crater holes appear on the surface.","Sprinkle the reserved golden fried onions on top. Seal tightly with foil and a heavy lid, then put on dum over low heat for 15 minutes. Rest 5 minutes before gently fluffing with a fork."],"tip":"The secret to a royal pulao is tying the fennel and coriander seeds in a cheesecloth bundle (potli) or straining thoroughly so no grit enters the rice. Never stir the rice aggressively once boiling.","published":"2026-11-05"},{"id":"shami-kabab","country":"Pakistan","name":"Traditional Beef Shami Kabab","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":60,"diff":"Medium","servings":"6 people (18 kababs)","img":"assets/shami-kabab-5a1e2f3d.webp","videos":{"en":"3ROkaVQTFsU","ru":"gf1CwhRvmV4","hi":"HFEMf2g3WWA","es":"6k67NYdyE1g","fr":"B4_y71_MXN0","ar":"NxovLWIZrKU","pt":"Ps888nhoKC0","rus":"o7sy0B_ZZEw","zh":"ZNPVtC5CcE8","ja":"NcJ8CvyyK04","de":"Ds27P1nUA-I","tr":"-F3oa9N7DLw","bn":"BFLtQSMiIZQ"},"shape":"wide","alt":"Crisp golden-brown Traditional Beef Shami Kababs on a white platter with mint chutney and ZaikaWorlds logo","desc":"Melt-in-the-mouth silk textured kababs made from slow-boiled beef chunks, split Bengal gram (chana daal), aromatic spices, fresh mint, coriander, and egg-dip shallow frying.","intro":"Shami Kababs are the quintessential tea-time snack and Eid delicacy across South Asia. Prepared by simmering tender beef cuts with chana daal and whole spices until completely dry, the mixture is pounded to a velvety fibre texture, formed into neat patties, dipped in whisked egg, and fried until golden and crisp.","ing":["Boneless beef chunks (cut into cubes) 750 g","Chana daal (split Bengal gram) 1 cup, rinsed and soaked 1 hour","Onion 1 large, roughly chopped","Ginger 2-inch piece chopped, garlic 10 whole cloves","Whole dry red chillies 8-10, cumin seeds 1 tbsp, black peppercorns 1 tsp","Black cardamom 2, cinnamon sticks 2, cloves 6","Salt 1 1/2 tsp, turmeric 1/2 tsp","Fresh mint leaves 1/2 cup finely chopped, coriander leaves 1/2 cup finely chopped","Green chillies 3, finely chopped","Egg 1 beaten for binding, plus 1 egg for dipping during frying","Oil for shallow frying"],"steps":["In a pressure cooker or deep pot, combine beef cubes, soaked chana daal, chopped onion, ginger, garlic, whole dry red chillies, cumin, whole spices, turmeric, salt, and 2 1/2 cups water.","Cook until the meat and daal are thoroughly tender and all excess water has completely evaporated. The mixture must be completely dry.","Discard large cinnamon sticks and black cardamom skins. While still warm, crush or grind the meat mixture using a food processor or mortar and pestle until it forms a smooth, stringy, fibrous paste (reshay-dar).","Allow the mixture to cool completely, then mix in chopped mint, fresh coriander, green chillies, and 1 beaten egg.","Grease your palms lightly with oil, take golf-ball sized portions, and shape them into smooth, round flat patties.","Heat 3 tablespoons of oil in a non-stick frying pan over medium heat.","Dip each kabab gently into whisked egg and shallow fry for 2-3 minutes per side until crisp and golden brown.","Drain on paper towels and serve hot alongside fresh mint raita, onion rings, and lemon wedges."],"tip":"Never leave residual moisture in the boiled meat-daal pot; if wet, cook it on high heat stirring constantly until dry, otherwise the kababs will break in the pan.","published":"2026-11-05"},{"id":"chicken-mandi","country":"Saudi Arabia","name":"Arabian Chicken Mandi","cat":"middle-eastern","catLabel":"Middle Eastern Dishes","veg":"nonveg","time":70,"diff":"Medium","servings":"4 people","img":"assets/chicken-mandi-7c3d1e9f.webp","videos":{"en":"sY_dCwGlGIs","ru":"8aPIsOo7m20","hi":"QqPJ_ToFRaE","es":"rO1ai-JVYeQ","fr":"VE7KbX7IcZU","ar":"Fk5aXyvcnvQ","pt":"hANTlHGE7qY","rus":"ujel3YzRo6M","zh":"-fB4FffUmL8","ja":"MeHmIOWJuZs","de":"FT9lZCR3ops","tr":"cu0G3kth134","bn":"OEaY2jvs8pQ"},"shape":"tall","alt":"Spiced roast chicken atop smoked basmati rice with toasted nuts and ZaikaWorlds logo","desc":"The signature Yemeni and Arabian feast: tender spice-marinated chicken roasted to golden perfection, served over smoky, fragrant basmati rice infused with hawaij spices and charcoal smoke.","intro":"Originally slow-cooked inside an underground tandoor (taboon), Chicken Mandi has captivated the world with its delicate balance of whole spices and charcoal aroma. Our foolproof home method creates golden-skinned roasted chicken dripping into aromatic rice, finished with the authentic dhungar coal smoke technique.","ing":["Whole chicken (cut into halves or skin-on bone-in quarters) 1.2 kg","Aged long-grain basmati rice 3 cups, soaked 30 mins","Mandi spice blend: 1 tbsp ground coriander, 1 tbsp cumin, 1 tsp turmeric, 1/2 tsp cardamom, 1/2 tsp cloves, 1 tsp black pepper","Saffron threads 1/4 tsp soaked in 2 tbsp warm rosewater or milk","Onion 2 medium, finely chopped","Green chillies 3 whole, dried black lime (loomi) 1 pierced","Butter or ghee 3 tbsp, olive oil 2 tbsp","Toasted slivered almonds and golden raisins for garnish","Lump of natural charcoal and 1 tsp ghee for the smoke dum"],"steps":["Prepare the spice rub: Mix the ground Mandi spices with salt, 1 tablespoon olive oil, and half of the saffron mixture. Rub thoroughly all over the chicken pieces, including under the skin. Let marinate for 30 minutes.","In an oven-safe heavy pot or Dutch oven, heat butter and remaining olive oil. Sauté onions until translucent and lightly golden.","Add dried black lime, whole cardamoms, cinnamon, and whole green chillies. Sauté for 2 minutes until fragrant.","Add the drained soaked basmati rice, 4 1/2 cups boiling water, and salt. Stir once.","Place an oven wire rack directly over the pot and arrange the spiced chicken pieces on the rack (or place chicken on top of the rice separated by parchment paper with holes).","Cover tightly with double foil to lock in steam. Bake in a preheated oven at 190°C (375°F) for 45 minutes until chicken is tender and rice is cooked.","Remove chicken and broil under high heat for 5 minutes until the skin turns crisp and golden.","Smoke finish: Place a small heatproof bowl or foil cup in the middle of the rice pot. Drop a red-hot charcoal piece inside, drizzle 1/2 teaspoon ghee over it, and immediately seal the lid for 5 minutes to infuse intense woodsmoke.","Fluff the rice, spread onto a large serving platter, arrange roast chicken on top, and scatter toasted almonds and raisins."],"tip":"The pierced dried black lime (loomi) and the 5-minute charcoal smoke infuse the authentic Gulf restaurant flavour. Do not omit the loomi.","published":"2026-11-05"},{"id":"butter-chicken","country":"India","name":"Murgh Makhani (Butter Chicken)","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":50,"diff":"Medium","servings":"4 people","img":"assets/butter-chicken-8e4d3a2b.webp","videos":{"en":"4P7Y5PL88bo","ru":"IgikHj23zFk","hi":"XS8H5GBy_ME","es":"l8gtxt3lo5E","fr":"S5AhyKfHoEw","ar":"lgctdvqpS_A","pt":"Fl_tlblKbBI","rus":"h35mlx7oPFQ","zh":"u-T6OL6iSvg","ja":"4JxVR2-xdo4","de":"GEV8vmZtrK8","tr":"8gJGmE5shno","bn":"_xOIpHX0w8w"},"shape":"wide","alt":"Velvety Murgh Makhani Butter Chicken in copper karahi with naan and ZaikaWorlds logo","desc":"Tandoori grilled spiced chicken simmered in an indulgent, velvety smooth tomato, cashew, and butter makhani gravy flavoured with fragrant kasuri methi.","intro":"Invented in Delhi, Butter Chicken (Murgh Makhani) is universally beloved for its silky contrast between smoky charred chicken pieces and the rich, velvety gravy sweetened gently by ripe tomatoes, cashew paste, and butter.","ing":["Boneless chicken thighs (cut into bite-sized pieces) 750 g","Yoghurt 1/2 cup, Kashmiri red chilli powder 2 tbsp, ginger-garlic paste 2 tbsp","Butter 4 tbsp, heavy cream 1/2 cup","Ripe tomatoes 6 large, pureed and strained","Cashew nuts 15, soaked and blended to a smooth paste","Kasuri methi (dried fenugreek leaves) 1 tbsp, lightly crushed","Garam masala 1 tsp, honey or sugar 1 tsp","Salt to taste, oil 2 tbsp"],"steps":["Marinate chicken in yoghurt, 1 tbsp Kashmiri chilli, 1 tbsp ginger-garlic, and salt for at least 30 minutes.","Sear chicken in a hot skillet with 2 tbsp oil until nicely charred on all edges (about 8-10 minutes). Set aside.","In a saucepan, melt 2 tbsp butter. Add remaining ginger-garlic paste and sauté for 1 minute.","Pour in tomato puree and simmer on medium heat for 12-15 minutes until raw smell disappears and oil surfaces.","Whisk in the smooth cashew paste and 1/2 cup water. Simmer 5 minutes until rich and creamy.","Add the seared chicken pieces, remaining butter, garam masala, and honey. Cook for 6 minutes.","Stir in heavy cream and crushed kasuri methi. Simmer on low for 2 minutes, then turn off heat.","Serve warm with garlic butter naan or fragrant basmati rice."],"tip":"Rubbing kasuri methi gently between your palms right before adding unlocks its fragrant herbal oils.","published":"2026-11-07"},{"id":"falooda","country":"Pakistan","name":"Royal Shahi Falooda","cat":"meetha","catLabel":"Desserts","veg":"veg","time":25,"diff":"Easy","servings":"4 glasses","img":"assets/falooda-ca19a4b2.webp","videos":{"en":"LL1hN53wk6Q","ru":"6ebvphHN2TA","hi":"PDTE4ilNqCs","es":"mbeqARRRPLg","fr":"KO1W9Cb4oKs","ar":"xEVO1y3mj-U","pt":"HAiEvo0jJ1g","rus":"JAk9tJvYoyg","zh":"-1qWhKWKiGc","ja":"cxkrFxIGfCw","de":"67pcipYZHV4","tr":"vlzT8UcgzJo","bn":"XQ-t31B7S6g"},"shape":"tall","alt":"Layered Royal Shahi Falooda in a tall glass with rose syrup, basil seeds, vermicelli sev, kulfa ice cream, and ZaikaWorlds logo","desc":"The ultimate royal summer dessert drink: chilled rose-scented milk layered with blooming basil seeds (tukhmariya), silky cornstarch vermicelli, and rich kulfa ice cream.","intro":"Originating in Persia and perfected during the Mughal era, Falooda is the grandest dessert drink of the subcontinent. Every sip and spoonful offers a delightful medley of crunchy basil seeds, cool ice cream, and fragrant rose essence.","ing":["Whole milk 1 litre, chilled and slightly reduced","Rooh Afza or rose syrup 1/2 cup","Basil seeds (sabja / tukhmariya) 2 tbsp, soaked in 1 cup water for 15 mins","Falooda sev (cornstarch vermicelli) 100 g, cooked and chilled in cold water","Traditional Kulfa or Vanilla ice cream 4 large scoops","Crushed pistachios and slivered almonds 3 tbsp","Tutti frutti or maraschino cherries for topping"],"steps":["In tall dessert glasses, pour 2 tablespoons of fragrant rose syrup into the base.","Add 2 generous tablespoons of soaked, plump basil seeds.","Layer 3 tablespoons of chilled falooda vermicelli over the seeds.","Gently pour chilled reduced milk until the glass is 3/4 full.","Top with a large scoop of dense kulfa or vanilla ice cream.","Drizzle a thin stream of rose syrup over the ice cream and garnish generously with chopped pistachios and almonds.","Serve immediately with a long spoon and a wide straw."],"tip":"Keep the cooked falooda sev submerged in ice water in the fridge until assembly so the strands remain bouncy and do not stick together.","published":"2026-11-07"},{"id":"chicken-shawarma","country":"Middle East","name":"Classic Chicken Shawarma","cat":"street","catLabel":"Street Food","veg":"nonveg","time":45,"diff":"Easy","servings":"4 wraps","img":"assets/chicken-shawarma-4b2a8d1e.webp","videos":{"en":"qTPZez9KXaA","ru":"yDVUaRmNcyI","hi":"NZIzqpQD8eA","es":"ZbOrqIwLyak","fr":"DpbKFXPdYaM","ar":"mn2RbApTkJ8","pt":"1PuNXuBW6xI","rus":"ojRTvt_R9CM","zh":"HAvEEeQWKms","ja":"rZVODj-oS5U","de":"uTLWGFbCUFM","tr":"5bc4e7o7dK8","bn":"hXyeLPMSPJc"},"shape":"wide","alt":"Classic Lebanese Chicken Shawarma with garlic toum and ZaikaWorlds logo","desc":"Tender spice-marinated chicken thighs seared crisp, wrapped in warm pita with creamy garlic toum, salty wild cucumber pickles, and golden fries.","intro":"Lebanese Chicken Shawarma is the undisputed king of Middle Eastern street food. Juicy chicken thighs marinated with warm spices, lemon juice, garlic, and cardamom, seared to charred perfection and rolled into warm flatbreads with garlic toum.","ing":["Boneless chicken thighs 700 g, sliced thinly","Garlic paste 2 tbsp, lemon juice 3 tbsp, olive oil 3 tbsp","Shawarma spices: ground cumin 1 tbsp, coriander 1 tbsp, paprika 1 tbsp, cardamom 1/2 tsp, cinnamon 1/4 tsp","Salt 1 1/2 tsp, black pepper 1 tsp","Pita bread or Lebanese flatbreads 4","Garlic toum or tahini sauce 1/2 cup","Pickled cucumbers and pickled turnips, sliced","Crisp French fries (optional for inside wrap)"],"steps":["In a bowl, mix olive oil, lemon juice, garlic paste, shawarma spices, and salt. Coat chicken slices thoroughly and marinate for 30 minutes.","Heat a large cast-iron skillet or grill pan over medium-high heat with 1 tablespoon of oil.","Sear chicken in batches without crowding until deeply charred on edges and fully cooked (about 6-8 minutes).","Warm the pita bread lightly on the same pan to pick up pan flavours.","Spread 2 generous tablespoons of garlic toum sauce across the centre of each pita.","Layer charred chicken shawarma strips, sliced pickles, and crispy french fries.","Roll tightly into wraps, toast on a dry hot pan for 1 minute for a crisp exterior, and serve immediately."],"tip":"Always use skinless chicken thighs instead of breast meat; thighs stay moist and tender under high-heat pan searing.","published":"2026-11-07"},{"id":"paneer-tikka","country":"India","name":"Tandoori Paneer Tikka","cat":"bbq","catLabel":"BBQ","veg":"veg","time":35,"diff":"Easy","servings":"4 people","img":"assets/paneer-tikka-3d8b2a1e.webp","videos":{"en":"AbKrkNr0Oc0","ru":"dg3FRcVkzgY","hi":"53RG-zGdSfs","es":"yiaRKt3JXb4","fr":"eFtZVVaKTAU","ar":"9m0pkgaV1EE","pt":"ORkG0DPmPS4","rus":"vYvU9F7mvhM","zh":"Q9MErRfah4U","ja":"35oacmyPvCo","de":"t-Pidhc8xzk","tr":"9u5CnKIYVlI","bn":"m8hyoo0ng7o"},"shape":"wide","alt":"Tandoori Paneer Tikka skewers with charred bell peppers, onions, and ZaikaWorlds logo","desc":"Succulent cubes of firm cottage cheese (paneer), crunchy bell peppers, and red onions marinated in spiced yoghurt and carom seeds, grilled to smoky charred perfection.","intro":"Tandoori Paneer Tikka is the undisputed star of vegetarian barbecue across India and Pakistan. Thick blocks of paneer absorb the smoky tandoori marinade made from thick hung curd, roasted gram flour (besan), Kashmiri chilli, and mustard oil.","ing":["Paneer (cottage cheese) 400 g, cut into 1.5-inch cubes","Bell peppers (capsicum) 2 diced, red onion 1 large cut into petals","Thick hung curd (Greek yoghurt) 1 cup","Mustard oil 2 tbsp, roasted gram flour (besan) 2 tbsp","Ginger-garlic paste 1 1/2 tbsp, Kashmiri red chilli powder 1 1/2 tbsp","Carom seeds (ajwain) 1/2 tsp crushed, chaat masala 1 tsp, garam masala 1/2 tsp","Lemon juice 1 tbsp, salt to taste","Melted butter for basting"],"steps":["In a mixing bowl, whisk mustard oil and Kashmiri red chilli powder until vibrant red. Whisk in hung curd, roasted gram flour, ginger-garlic paste, ajwain, garam masala, lemon juice, and salt.","Add the paneer cubes, diced capsicum, and onion petals to the marinade. Coat gently with your hands and rest for 30 minutes.","Thread paneer alternately with bell pepper and onion petals onto skewers.","Heat a grill pan, barbecue grill, or preheat oven to 220°C (430°F).","Grill or bake skewers for 10-12 minutes, turning halfway and basting with melted butter until the edges are nicely charred.","Sprinkle generously with chaat masala and serve piping hot with spicy mint-coriander chutney and lemon wedges."],"tip":"Heating mustard oil before mixing into the yoghurt creates the signature authentic dhaba tandoori pungency and aroma.","published":"2026-11-07"},{"id":"keema-naan","country":"Pakistan","name":"Stuffed Keema Naan","cat":"nashta","catLabel":"Breakfast","veg":"nonveg","time":45,"diff":"Medium","servings":"4 naans","img":"assets/keema-naan-8a3c1f9b.webp","videos":{"en":"tpp9d_93QBI","ru":"ajYMnEovO9I","hi":"RmjngUtzGu8","es":"ShZwFNAqTf4","fr":"vZoD3n8aK8k","ar":"C5XKZ_xm4G0","pt":"2svc0N0KuA8","rus":"NfWNIJ223p8","zh":"vifaEP8iF5U","ja":"4PoRV-K65ng","de":"dr_VGUs8ipI","tr":"JDkI8H5AVPA","bn":"Cn8fwzY_jhA"},"shape":"wide","alt":"Stuffed baked Keema Naan with butter and ZaikaWorlds logo","desc":"Soft, pillowy tandoori flatbread stuffed with a savoury, spiced minced mutton or beef filling, brushed with melted butter and fresh coriander.","intro":"Keema Naan is a lavish breakfast and celebratory meal across Lahore and Delhi. The yeast-leavened dough provides a crisp, chewy crust that encases a succulent interior of spiced minced meat, whole coriander, and chopped green chillies.","ing":["All-purpose flour (maida) 3 cups, instant yeast 1 tsp, sugar 1 tsp","Warm milk 1/2 cup, plain yoghurt 3 tbsp, warm water as needed","Minced mutton or beef (keema) 400 g, thoroughly washed and drained dry","Onion 1 medium finely chopped and squeezed of excess water","Ginger-garlic paste 1 tbsp, green chillies 3 finely chopped","Crushed coriander seeds 1 tbsp, cumin powder 1 tsp, garam masala 1/2 tsp","Fresh mint and coriander leaves 3 tbsp finely chopped, salt to taste","Butter and sesame seeds / kalonji for topping"],"steps":["Prepare dough: Knead flour, yeast, sugar, salt, yoghurt, and warm milk into a soft, elastic dough. Cover and let rise in a warm spot for 1 hour until doubled.","Prepare filling: In a bowl, mix minced meat, chopped onion, ginger-garlic paste, green chillies, crushed coriander, cumin, garam masala, mint, coriander, and salt until completely uniform.","Divide dough and filling into 4 equal portions.","Flatten a dough ball slightly, place a meat portion in the centre, bring the edges together to seal tightly, and gently roll out into an oval or round naan.","Brush top with water and press sesame seeds and chopped coriander onto the surface.","Cook on a smoking hot iron tawa, flip to cook the underside, or bake at 230°C (450°F) for 6-8 minutes until blistered and golden.","Brush immediately with melted butter and serve with plain yoghurt raita."],"tip":"Ensure the minced meat filling has no excess moisture so the dough does not tear during rolling.","published":"2026-11-07"},{"id":"dal-makhani","country":"India","name":"Restaurant-Style Dal Makhani","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":75,"diff":"Medium","servings":"5 people","img":"assets/dal-makhani-6c1d8e2a.webp","videos":{"en":"q3ehnBT5WUE","ru":"ueC4H81VJb0","hi":"V7weKEGKU48","es":"vlJt5shaRP4","fr":"9WRQC8huEp4","ar":"TRQwcbteOcw","pt":"suIqwdkGQRc","rus":"QnN7wSvJ0l8","zh":"bHEHZINmFjI","ja":"FB3rTW5JkK8","de":"Y0FanvyXNNk","tr":"oLye9ffWbwg","bn":"NJKOBsTB5fA"},"shape":"wide","alt":"Creamy rich Dal Makhani with butter and ZaikaWorlds logo","desc":"Slow-simmered whole black lentils (urad daal) and red kidney beans (rajma) cooked in a rich tomato, butter, and cream gravy with aromatic spices.","intro":"Originating in Punjab, Dal Makhani is renowned for its velvety texture and deep, complex flavour achieved by hours of gentle simmering with pure butter, cream, and subtle whole spices.","ing":["Whole black urad daal 1 cup, rajma (red kidney beans) 1/4 cup, soaked overnight (8-10 hours)","Butter 4 tbsp, heavy cream 1/3 cup","Tomato puree 1 1/2 cups (from 4 ripe pureed tomatoes)","Ginger-garlic paste 2 tbsp, Kashmiri red chilli powder 1 1/2 tbsp","Garam masala 1/2 tsp, kasuri methi 1 tsp lightly crushed","Salt to taste, green chillies 2 slit"],"steps":["In a pressure cooker or deep pot, cook the soaked black lentils and kidney beans with 5 cups water and 1 tsp salt until completely soft and creamy (about 45 mins).","Using the back of a ladle, lightly mash some of the lentils against the side of the pot to release starches and create creaminess.","In a separate saucepan, melt 2 tbsp butter. Add ginger-garlic paste and sauté for 1 minute until fragrant.","Add tomato puree, Kashmiri chilli powder, and slit green chillies. Cook on medium heat until oil separates (about 10 mins).","Pour the cooked lentil mixture into the tomato masala. Mix well and bring to a simmer.","Simmer on very low heat for 30 minutes, stirring occasionally and adding warm water as needed to maintain a creamy gravy.","Finish by stirring in remaining butter, heavy cream, garam masala, and crushed kasuri methi.","Serve hot garnished with a swirl of cream alongside garlic naan or jeera rice."],"tip":"The secret to Dal Makhani's creamy silkiness is cooking it on very low heat and gentle mashing, allowing the lentils' natural starch to emulsify with butter.","published":"2026-11-07"},{"id":"chicken-resmi-kebab","country":"Pakistan","name":"Silky Chicken Reshmi Kabab","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":35,"diff":"Easy","servings":"4 people","img":"assets/chicken-resmi-kebab-7b4e1a9c.webp","videos":{"en":"jwIXqeSJbuM","ru":"ZFlH1ZcuYQ4","hi":"9EUXkABgCzE","es":"P5GnsETnSZM","fr":"8DNN0Co3wtY","ar":"6AtdkrfeCPc","pt":"IO28bk2mZhw","rus":"8VScVIrS7oo","zh":"9pPlIXttHJE","ja":"8mzTuVA6PvE","de":"sLAVnTWTG3Q","tr":"sh3RKiwrLPw","bn":"jSAOABchQQs"},"shape":"wide","alt":"Silky Chicken Reshmi Kabab skewers with ZaikaWorlds logo","desc":"Melt-in-the-mouth silk-textured chicken breast skewers marinated in cashew cream, fresh malai, cheese, green chillies, and subtle Mughlai spices.","intro":"Named 'Reshmi' (silken) for its exceptionally velvety and tender texture, this Mughlai delicacy features minced or cubed chicken enveloped in fresh cream, cashew paste, and aromatic spices before being grilled over gentle coals.","ing":["Boneless chicken breast or thigh (cubed or minced) 600 g","Fresh cream or malai 3 tbsp, cashew nut paste 2 tbsp","Grated processed cheese or mozzarella 2 tbsp","Hung curd 2 tbsp, ginger-garlic paste 1 1/2 tbsp","Green chilli paste 1 tbsp, white pepper powder 1 tsp","Mace and green cardamom powder 1/2 tsp, roasted cumin powder 1/2 tsp","Lemon juice 1 tbsp, salt to taste, melted butter for brushing"],"steps":["In a food processor, blend the chicken lightly or combine cubes with cashew paste, fresh cream, grated cheese, hung curd, and ginger-garlic paste.","Season with green chilli paste, white pepper, mace-cardamom powder, cumin, lemon juice, and salt.","Mix thoroughly and refrigerate for at least 45 minutes to let the flavours permeate.","Thread chicken gently onto flat skewers.","Heat a grill pan, charcoal BBQ, or oven broiler to high heat.","Grill skewers for 8-10 minutes, rotating frequently and brushing with melted butter until cooked through with light golden spots.","Serve immediately with mint raita, sliced lemons, and buttered rumali roti."],"tip":"Adding grated cheese and cashew paste creates the velvety emulsified barrier that keeps lean chicken breast exceptionally juicy.","published":"2026-11-07"},{"id":"lahori-fried-fish","country":"Pakistan","name":"Crispy Lahori Fried Fish","cat":"fish","catLabel":"Fish Dishes","veg":"nonveg","time":30,"diff":"Easy","servings":"4 people","img":"assets/lahori-fried-fish-2d9c4e8f.webp","videos":{"en":"s7gD34yOi1U","ru":"0u7S-UgYdAo","hi":"pYodxDXkMwE","es":"jwBEuVNuAtw","fr":"n7AfnlK_-qk","ar":"XDnDcPrc2aA","pt":"ogYAbcaghTc","rus":"sgspywp1biw","zh":"aF1BzDjpThw","ja":"w_2AhRFzRVc","de":"UQgKpkeEBwU","tr":"dPcHbbW2HTI","bn":"xOuRLAzLPLg"},"shape":"wide","alt":"Crispy Lahori Fried Fish with chaat masala and ZaikaWorlds logo","desc":"Crispy spiced freshwater fish fillets marinated in carom seeds (ajwain), garlic, red chillies, and lemon juice, coated in an airy spiced gram-flour batter and deep-fried.","intro":"A winter street-food legend of Gawalmandi in Lahore, Lahori Fried Fish is celebrated for its feather-light, crunchy exterior and steaming, moist fish flakes inside seasoned with aromatic ajwain and crushed spices.","ing":["White fish fillets (Rohu, Sole, or Cod) cut into thick slices 750 g","Gram flour (besan) 1 cup, rice flour 2 tbsp (for extra crunch)","Carom seeds (ajwain) 1 tbsp crushed between palms","Ginger-garlic paste 2 tbsp, lemon juice 3 tbsp","Crushed red chilli flakes 1 tbsp, roasted coriander powder 1 tbsp, cumin powder 1 tsp","Turmeric 1/2 tsp, chaat masala 1 tsp, salt to taste","Mustard oil or vegetable oil for deep frying"],"steps":["Wash and thoroughly dry fish pieces with kitchen towels.","Marinate fish with lemon juice, ginger-garlic paste, crushed ajwain, turmeric, and 1 tsp salt for 20 minutes.","In a bowl, mix gram flour, rice flour, chilli flakes, coriander powder, cumin, and a little cold water to form a smooth thick coating batter.","Coat each marinated fish piece evenly in the batter.","Heat oil in a wok or deep fryer to 180°C (350°F).","Gently slide fish pieces into the hot oil in batches without crowding. Fry for 4-5 minutes until crisp and golden brown.","Drain on a wire rack to maintain crunchiness.","Dust immediately with spicy chaat masala and serve hot with sweet-and-sour tamarind chutney and onion rings."],"tip":"Double-frying for 1 minute on high heat right before serving gives that signature street-vendor ultra-crunchy shell.","published":"2026-11-07"},{"id":"zafrani-mutton-korma","country":"Pakistan","name":"Shahi Zafrani Mutton Korma","cat":"desi","catLabel":"Desi Dishes","veg":"nonveg","time":70,"diff":"Medium","servings":"5 people","img":"assets/zafrani-mutton-korma-5f1e8a3b.webp","videos":{"en":"jKFIsDh0n7s","ru":"Rh1ldT9mZxs","hi":"72Zp16UfXsU","es":"wehK0VzHkHQ","fr":"e_PB0Bx7q-Q","ar":"dlMIzniG6qU","pt":"TGwCeDOBHJ4","rus":"vctGozyAgVk","zh":"CtMN_9Dt2x0","ja":"r_KMxfdy9ss","de":"xvdkWSY3Omg","tr":"zymOvwk59Zs","bn":"KhjVSrEBVGI"},"shape":"tall","alt":"Shahi Zafrani Mutton Korma in golden aromatic gravy with ZaikaWorlds logo","desc":"Tender bone-in mutton pieces cooked in a rich, velvety browned-onion and yoghurt gravy infused with aromatic saffron threads, mace, and kewra water.","intro":"The royal crown of Mughlai gastronomy, Shahi Zafrani Korma relies on the art of caramelised onions, whisked yoghurt, and freshly ground whole spices without tomatoes, producing a lustrous, grain-textured (danedar) gravy.","ing":["Bone-in mutton (shoulder cuts) 800 g","Onions 3 large, thinly sliced and fried golden brown (birista)","Plain yoghurt 1 cup, whisked smoothly","Ghee 1/2 cup","Ginger-garlic paste 2 tbsp, Kashmiri red chilli powder 1 1/2 tbsp, coriander powder 2 tbsp","Whole spices: 2 black cardamoms, 5 green cardamoms, 1 cinnamon stick, 6 cloves","Saffron threads 1/4 tsp bloomed in 2 tbsp warm milk, kewra water 1 tsp","Mace and nutmeg powder 1/4 tsp, salt to taste"],"steps":["In a heavy-bottom pot, heat ghee and fry the whole spices (cardamoms, cinnamon, cloves) for 30 seconds until aromatic.","Add mutton pieces and ginger-garlic paste. Bhunai (sear) on high heat for 6-8 minutes until meat changes colour.","Lower heat, add coriander powder, red chilli powder, and salt. Stir well.","Whisk yoghurt smoothly and stir into the pot. Cook until ghee separates from the masala.","Add 2 cups hot water, cover tightly, and simmer on low heat for 45-50 minutes until meat is tender.","Crush the golden fried onions with your fingers and stir into the gravy. The gravy will instantly thicken and develop its signature danedar texture.","Stir in the saffron milk, mace-nutmeg powder, and kewra water.","Simmer covered on low dum for 5 minutes before serving with hot sheermaal or rogheni naan."],"tip":"Never blend the fried onions in a mixer with water; crush them coarsely with your fingers or a rolling pin for the authentic grain-textured korma gravy.","published":"2026-11-07"},{"id":"motichoor-laddu","country":"India","name":"Shahi Motichoor Laddu","cat":"meetha","catLabel":"Desserts","veg":"veg","time":40,"diff":"Medium","servings":"15 laddus","img":"assets/motichoor-laddu-9a4c2d1e.webp","videos":{"en":"icfEH8voAI0","ru":"OmmY22hcfDM","hi":"utnlJGaCsBI","es":"UYuttEmM7hY","fr":"tf8cXxbkaz4","ar":"uwtrFrgQRgY","pt":"iy-GjeSstUs","rus":"Jph9G2ndIwQ","zh":"vVygFV842zE","ja":"FMe_skS8Bfc","de":"FFc549mjo1Y","tr":"2j1-hm3prZE","bn":"D1reGAF1-WE"},"shape":"wide","alt":"Festive Shahi Motichoor Laddu with pistachios and ZaikaWorlds logo","desc":"Melt-in-mouth traditional festive sweets made from micro gram-flour pearls (boondi) fried in pure ghee, soaked in saffron-cardamom sugar syrup, and shaped into tender spheres.","intro":"Motichoor Laddu, literally 'crushed pearls', is celebrated across South Asia as the ultimate sweet of festive joy. Tiny pearls of chickpea batter are fried in pure desi ghee, soaked in warm saffron syrup, and pressed into tender, fragrant spheres.","ing":["Gram flour (fine besan) 2 cups","Pure desi ghee for deep frying","Sugar 2 cups, water 1 1/2 cups","Saffron threads 1/4 tsp, green cardamom powder 1 tsp","Kewra essence 1/2 tsp, edible orange food colour a pinch","Melon seeds (magaz) 2 tbsp roasted, slivered pistachios for garnish"],"steps":["In a bowl, whisk gram flour and water to create a smooth, lump-free, flowing batter of pouring consistency.","Make sugar syrup: Combine sugar and water in a pan, bring to a boil, and simmer for 5 minutes until it reaches half-string consistency. Stir in saffron, cardamom powder, orange colour, and kewra.","Heat desi ghee in a wide frying pan over medium heat.","Hold a perforated ladle (boondi jhara with tiny holes) 4 inches above the hot ghee and pour a ladleful of batter. Tap gently so tiny pearls fall into the ghee.","Fry boondi for just 40-50 seconds (do not make them crispy). Drain and immediately transfer hot boondi into the warm sugar syrup.","Let boondi soak for 15-20 minutes until all syrup is absorbed.","Add roasted melon seeds, mix well, and shape warm mixture into neat, round laddus with your palms.","Garnish with slivered pistachios and silver leaf before serving."],"tip":"The sugar syrup must remain warm when adding the fried boondi so the tiny pearls soak the syrup all the way to the core without turning dry.","published":"2026-11-07"},{"id":"kashmiri-chai","country":"Pakistan","name":"Shahi Kashmiri Chai (Pink Tea)","cat":"meetha","catLabel":"Desserts","veg":"veg","time":45,"diff":"Medium","servings":"4 cups","img":"assets/kashmiri-chai-8f2c1a9d.webp","shape":"wide","alt":"Authentic pink Kashmiri Chai topped with crushed pistachios and ZaikaWorlds logo","desc":"Traditional Kashmiri pink tea brewed from green tea leaves, star anise, baking soda for natural rosy color, simmered with whole milk, cardamom, and garnished with crushed nuts.","intro":"Kashmiri Chai, famously known as Noon Chai or Pink Tea, is an iconic Himalayan beverage with a distinct pastel pink hue and luxurious nutty aroma. Brewed through aerating green tea leaves with cold water and baking soda, then enriched with rich milk and ground pistachios.","ing":["Kashmiri green tea leaves 2 tbsp","Cold ice water 4 cups","Baking soda 1/4 tsp","Green cardamom pods 4 crushed, star anise 1 piece","Full cream milk 3 cups","Sugar 2 tbsp (or pinch of salt for authentic salty version)","Crushed pistachios and almonds 3 tbsp for garnish"],"steps":["In a saucepan, combine tea leaves, star anise, crushed cardamoms, and 2 cups of water. Bring to a rolling boil over medium heat.","Add baking soda and whisk vigorously for 2 minutes as the decoction turns deep purple-red.","Pour in 2 cups of chilled ice water from a height while whisking continuously (aeration shock) to develop the natural rich pink pigment.","Simmer until liquid reduces to half. Strain the concentrated kehwa.","In another pan, heat full-cream milk and bring to a simmer. Add sugar or salt to taste.","Pour the warm kehwa into the milk. Watch it instantly turn into a gorgeous pastel pink tea.","Simmer for 2 minutes, pour into cups, and lavishly garnish with crushed almonds and pistachios."],"tip":"Whisking cold ice water into boiling kehwa from a height creates the aeration shock essential for getting that signature natural pink color.","published":"2026-11-10"},{"id":"chicken-malai-boti","country":"Pakistan","name":"Creamy Chicken Malai Boti","cat":"bbq","catLabel":"BBQ","veg":"non-veg","time":35,"diff":"Easy","servings":"4 log","img":"assets/chicken-malai-boti-7d3a1e8f.webp","shape":"wide","alt":"Grilled Creamy Chicken Malai Boti skewers with fresh coriander and ZaikaWorlds logo","desc":"Melt-in-mouth boneless chicken cubes marinated in fresh heavy cream, Greek yogurt, green chilies, white pepper, and roasted cumin, grilled over coals to tender perfection.","intro":"Chicken Malai Boti is Pakistan's undisputed king of creamy BBQ. Succulent cubes of chicken breast or thigh are coated in a rich marinade of fresh dairy cream, yogurt, white pepper, and aromatic spices, resulting in charred, butter-soft bites that dissolve on the palate.","ing":["Boneless chicken breast or thighs cut into cubes 750g","Fresh thick dairy cream 1/2 cup","Hung yogurt or thick curd 1/2 cup","Ginger-garlic paste 1 1/2 tbsp","Green chili paste 1 tbsp","White pepper powder 1 tsp, black pepper 1/2 tsp","Roasted cumin powder 1 tsp, garam masala powder 1/2 tsp","Lemon juice 2 tbsp, melted butter for basting, salt 1 tsp"],"steps":["Pat chicken cubes completely dry with paper towels.","In a large bowl, whisk together heavy cream, yogurt, ginger-garlic paste, green chili paste, lemon juice, white pepper, cumin, garam masala, and salt.","Coat chicken thoroughly in the marinade. Cover and refrigerate for at least 3-4 hours (or overnight for supreme tenderness).","Thread marinated chicken cubes onto skewers, leaving slight space between pieces for even cooking.","Grill over hot coals or cook in a cast-iron grill pan on medium-high heat for 12-14 minutes, turning skewers frequently.","Brush generously with melted butter during the last 2 minutes of cooking for a glossy golden char.","Serve sizzling hot with mint-coriander chutney, sliced red onions, and hot tandoori naan."],"tip":"Never skip drying the chicken cubes before marinating; excess moisture dilutes the rich cream coat and prevents proper searing.","published":"2026-11-10"},{"id":"mutton-shinwari-karahi","country":"Pakistan","name":"Peshawari Mutton Shinwari Karahi","cat":"desi","catLabel":"Desi Dishes","veg":"non-veg","time":50,"diff":"Medium","servings":"5 log","img":"assets/mutton-shinwari-karahi-3b8e2a1d.webp","shape":"wide","alt":"Sizzling Peshawari Mutton Shinwari Karahi with green chilies and ZaikaWorlds logo","desc":"Authentic rustic Pashtun karahi cooked with fresh mutton, animal fat or oil, ripe tomatoes, green chilies, and black pepper with zero onions or powdered spices.","intro":"Hailing from Khyber Pakhtunkhwa's Shinwari tribe, this iconic karahi is celebrated for its minimalistic cooking method that lets the natural rich flavors of tender mutton take center stage. Cooked simply with juicy tomatoes, green chilies, and coarse black pepper in a cast iron wok.","ing":["Fresh young mutton (mix bone-in cuts) 1 kg","Cooking oil or rendered mutton fat 1/2 cup","Ripe red tomatoes 6-7 cut in halves","Fresh garlic paste 2 tbsp diluted in 1/2 cup water","Green chilies slit lengthwise 8-10 pieces","Coarsely cracked black pepper 1 1/2 tsp","Salt 1 1/2 tsp, fresh julienned ginger 2 tbsp"],"steps":["Heat oil in a heavy-bottom cast iron karahi over high flame. Add mutton pieces and salt.","Fry the mutton for 6-8 minutes until light golden and searing.","Pour in the garlic water and 1 cup plain water. Cover with lid, lower heat to medium-low, and simmer for 30 minutes until mutton is 80% tender.","Uncover and arrange tomato halves skin-side up over the meat. Cover again for 8 minutes until skins soften.","Remove tomato skins with tongs. Use a wooden spoon to mash the soft tomato pulp directly into the simmering meat juices.","Turn flame to high and bhunai (stir-fry continuously) until oil separates cleanly and water evaporates.","Add slit green chilies and cracked black pepper. Toss for 2 minutes on high heat.","Garnish with lots of julienned ginger and serve sizzling in the karahi with hot Roghani naan."],"tip":"Traditional Shinwari karahi contains no onion, red chili, or turmeric; the magic lies entirely in the sear of the meat, sweet tomato reduction, and fresh cracked black pepper.","published":"2026-11-10"},{"id":"fish-tikka","country":"Pakistan","name":"Tandoori Fish Tikka","cat":"fish","catLabel":"Fish Dishes","veg":"non-veg","time":30,"diff":"Easy","servings":"4 log","img":"assets/fish-tikka-9a1c2d3e.webp","shape":"wide","alt":"Charred Tandoori Fish Tikka cubes with lemon and ZaikaWorlds logo","desc":"Firm boneless fish fillets marinated in tandoori spices, ajwain (carom seeds), mustard oil, thick yogurt, and lemon juice, grilled with a smoky charred edge.","intro":"Tandoori Fish Tikka is a seafood lover's ultimate barbecue delight. Firm cubes of fresh fish are coated in an ajwain-scented yogurt marinade spiked with Kashmiri chili and mustard oil, then swiftly charred over intense embers to lock in moisture and flakiness.","ing":["Boneless firm fish fillets (Surmai, Salmon, or Basa) cut into 1.5-inch cubes 750g","Thick hung yogurt 1/2 cup","Mustard oil 2 tbsp","Carom seeds (ajwain) 1 tsp crushed","Ginger-garlic paste 1 1/2 tbsp","Kashmiri red chili powder 1 1/2 tsp, turmeric powder 1/2 tsp","Roasted gram flour (besan) 2 tbsp","Lemon juice 2 tbsp, chaat masala 1 tsp, salt 1 tsp"],"steps":["Rinse fish cubes gently, pat completely dry, and lightly rub with 1 tbsp lemon juice and 1/2 tsp salt. Rest for 10 minutes.","In a bowl, mix roasted gram flour, mustard oil, thick yogurt, ajwain, Kashmiri chili, turmeric, ginger-garlic paste, and remaining lemon juice into a smooth marinade.","Gently coat fish cubes with marinade. Let sit for 25-30 minutes (do not marinate fish too long).","Skewer fish cubes carefully. Grill on medium-high heat for 8-10 minutes, basting with melted butter once halfway through.","Ensure exterior develops appetizing charred spots while the center remains juicy and tender.","Sprinkle tangy chaat masala on top and serve with lemon wedges, pickled onions, and mint chutney."],"tip":"Fish cooks much faster than chicken. Keep the heat medium-high and avoid overcooking beyond 10 minutes to retain supreme flakiness.","published":"2026-11-10"},{"id":"achari-gosht","country":"Pakistan","name":"Shahi Achari Gosht","cat":"desi","catLabel":"Desi Dishes","veg":"non-veg","time":55,"diff":"Medium","servings":"5 log","img":"assets/achari-gosht-4c2d1e9f.webp","shape":"wide","alt":"Tangy Shahi Achari Gosht with stuffed pickle chilies and ZaikaWorlds logo","desc":"Aromatic, tangy North Indian and Pakistani meat curry infused with freshly roasted pickling spices (fennel, kalonji, mustard, methi seeds) and stuffed green chilies.","intro":"Achari Gosht combines the bold, zesty flavor profile of homemade mango pickles with melt-in-mouth braised meat. Coarsely ground pickling spices simmered in a yogurt and tomato gravy create an irresistible tangy-spicy harmony that awakens every taste bud.","ing":["Mutton or beef bone-in pieces 800g","Yogurt whisked 1 cup","Cooking oil 1/2 cup","Onions finely sliced 2 medium","Ginger-garlic paste 2 tbsp","Tomatoes pureed 3 medium","Pickling spice blend (fennel seeds 1 tsp, nigella/kalonji 1/2 tsp, mustard seeds 1/2 tsp, fenugreek/methi 1/4 tsp, cumin 1 tsp)","Large mild green chilies for stuffing 6 pieces","Red chili flakes 1 tsp, coriander powder 1 tbsp, turmeric 1/2 tsp, salt 1 tsp"],"steps":["Coarsely grind half of the pickling spices. Mix with 1 tbsp lemon juice and a pinch of chaat masala. Slit large green chilies and stuff them with this tangy spice mixture; set aside.","Heat oil in a heavy pot. Add sliced onions and fry until golden brown.","Add whole remaining pickling spices (kalonji, fennel, mustard, cumin) and let them crackle for 30 seconds until aromatic.","Add ginger-garlic paste and meat. Sauté over high heat for 6-8 minutes until meat changes color.","Add coriander powder, red chili flakes, turmeric, salt, and tomato puree. Cook for 5 minutes.","Stir in whisked yogurt, lower heat, cover tightly, and simmer for 35-40 minutes until meat is completely fork-tender.","Place stuffed green chilies on top of the curry, cover, and steam on low flame (dum) for 8 minutes until chilies soften and infused oil floats to the top.","Serve steaming hot with fragrant cumin rice or hot kulchas."],"tip":"Do not grind the fenugreek (methi dana) too finely as it can impart bitterness; keep the pickling spices coarsely crushed for signature aroma.","published":"2026-11-10"},{"id":"shahi-kulfi-falooda","country":"Pakistan","name":"Traditional Shahi Kulfi","cat":"meetha","catLabel":"Desserts","veg":"veg","time":50,"diff":"Easy","servings":"6 servings","img":"assets/shahi-kulfi-falooda-5e1f8a2b.webp","shape":"wide","alt":"Rich frozen Shahi Malai Kulfi with saffron, pistachios, and ZaikaWorlds logo","desc":"Dense, velvety traditional frozen dairy dessert slow-simmered from caramelized whole milk, enriched with khoya (mawa), saffron, cardamom, and chopped pistachios.","intro":"Often hailed as the traditional ice cream of the Indian subcontinent, Kulfi is far denser, creamier, and richer than regular churned ice cream. Made by slowly reducing full-cream milk until caramelized and thick, it provides an exquisite melt-in-mouth finish to any feast.","ing":["Full-cream whole milk 1.5 liters","Mawa or khoya crumbled 1/2 cup (or condensed milk 1/2 cup)","Sugar 1/2 cup","Green cardamom powder 1 tsp","Saffron strands soaked in 2 tbsp warm milk 1/4 tsp","Slivered almonds and pistachios 4 tbsp","Rose water or kewra water 1 tsp"],"steps":["In a heavy-bottomed, wide pan, bring whole milk to a boil over medium-high heat, stirring constantly to prevent scorching.","Reduce heat to medium-low. Keep scraping the malai (clotted cream) from the sides and bottom back into the simmering milk.","Simmer for 35-40 minutes until the milk volume reduces to one-third and attains a creamy beige color.","Add crumbled mawa, sugar, cardamom powder, and saffron-infused milk. Whisk thoroughly until smooth.","Simmer for another 5 minutes, then stir in chopped almonds, pistachios, and kewra water. Turn off heat.","Allow the thickened rabri mixture to cool down completely to room temperature.","Pour into traditional metal kulfi moulds or popsicle containers. Seal tightly and freeze for at least 8 hours or overnight.","Dip moulds in lukewarm water for 5 seconds, unmould onto dessert plates, slice into rounds, and garnish with extra pistachios."],"tip":"Simmering slowly and scraping back the clotted cream layer (malai) into the milk gives authentic kulfi its signature grainy, ultra-rich texture.","published":"2026-11-10"},{"id":"chicken-white-handi","country":"Pakistan","name":"Restaurant Chicken White Handi","cat":"desi","catLabel":"Desi Dishes","veg":"non-veg","time":35,"diff":"Easy","servings":"4 log","img":"assets/chicken-white-handi-2a9d8c1e.webp","shape":"wide","alt":"Creamy Chicken White Handi with green chilies, cream swirl, and ZaikaWorlds logo","desc":"Mild, luxurious white chicken curry simmered in clay handi with cashew cream, yogurt, white pepper, roasted cumin, and butter without red chili or turmeric.","intro":"A beloved staple in fine-dining restaurants across Lahore and Karachi, Chicken White Handi is famous for its velvety, creamy white gravy and delicately balanced spices. Cooked in an authentic clay pot, boneless chicken cubes absorb rich notes of yogurt, cream, and freshly crushed white pepper.","ing":["Boneless chicken breast or thigh cubes 750g","Cooking oil 3 tbsp + butter 2 tbsp","Ginger-garlic paste 2 tbsp","Cashew nut paste 3 tbsp (soaked in warm water and blended)","Whisked yogurt 1/2 cup","Fresh dairy cooking cream 1/2 cup","Green chilies finely chopped 3 pieces","White pepper powder 1 1/2 tsp, black pepper 1/2 tsp","Roasted cumin powder 1 tsp, coriander powder 1 tsp","Dried fenugreek leaves (kasuri methi) 1 tsp, salt 1 tsp"],"steps":["Heat oil and butter in an earthen clay handi or heavy pan over medium flame. Add ginger-garlic paste and sauté for 1 minute until fragrant.","Add boneless chicken cubes and cook for 5-6 minutes until chicken turns opaque and white.","Lower flame and stir in whisked yogurt and blended cashew paste. Mix continuously until smoothly incorporated.","Add white pepper, black pepper, cumin powder, coriander powder, and salt. Cook for 8 minutes until chicken is tender and sauce thickens.","Pour in fresh cream and chopped green chilies. Simmer gently on low flame for 3 minutes (do not boil rapidly after adding cream).","Rub kasuri methi between your palms and sprinkle over the curry along with fresh butter.","Serve hot directly from the clay handi with garlic naan or butter paratha."],"tip":"Use white pepper instead of red chili powder to maintain the pristine ivory color of the curry while delivering deep aromatic warmth.","published":"2026-11-10"},{"id":"charsi-tikka","country":"Pakistan","name":"Peshawari Charsi Chicken Tikka","cat":"bbq","catLabel":"BBQ","veg":"non-veg","time":40,"diff":"Easy","servings":"4 log","img":"assets/charsi-tikka-6b1e8a2d.webp","shape":"wide","alt":"Smoky Peshawari Charsi Chicken Tikka pieces with lemon and ZaikaWorlds logo","desc":"Namak Mandi Peshawar's legendary chicken tikka made with coarse rock salt, rendered fat, tomatoes, and green chilies, roasted over red hot charcoal.","intro":"Originating from the bustling Namak Mandi in Peshawar, Charsi Tikka is an icon of primal, open-fire barbecue. Prepared with minimal seasoning—predominantly rock salt and succulent fats—this dish celebrates the pure, unmasked taste of high-heat charcoal-roasted chicken.","ing":["Whole chicken cut into 16 bone-in pieces 1 kg","Coarse Himalayan rock salt 1 1/2 tsp","Melted animal fat or cooking oil 1/2 cup","Fresh garlic water 1/2 cup (3 tbsp crushed garlic steeped in warm water)","Green chilies crushed coarsely 2 tbsp","Juice of 2 fresh lemons for final basting"],"steps":["Wash chicken pieces thoroughly and make deep angular incisions on thicker meat portions.","Rub chicken generously with coarse rock salt and garlic water. Rest for 20 minutes.","Mount chicken pieces onto heavy iron skewers.","Place over live white-hot hardwood coals. Let sear for 5-6 minutes per side until the edges turn crusty golden.","Brush chicken lavishly with melted fat/oil every 3 minutes, allowing fat drippings to flare onto the embers and smoke-infuse the meat.","Sprinkle crushed green chilies and lemon juice during the final 3 minutes of roasting.","Transfer onto flatbread, garnish with fresh mint leaves and sliced lemons, and serve piping hot."],"tip":"The secret to authentic Charsi flavor is the fat basting over charcoal embers; the rising aromatic smoke gives the meat its unmatched rustic aroma.","published":"2026-11-10"},{"id":"tawa-chicken-fry","country":"Pakistan","name":"Lahori Tawa Chicken Fry","cat":"street-food","catLabel":"Street Food","veg":"non-veg","time":30,"diff":"Easy","servings":"4 log","img":"assets/tawa-chicken-fry-1e9d8c2b.webp","shape":"wide","alt":"Sizzling Lahori Tawa Chicken Fry on flat griddle with ZaikaWorlds logo","desc":"Spicy, tangy street-style chicken cooked on a giant iron tawa with crushed green chilies, tomatoes, yogurt, lemon juice, and freshly ground garam masala.","intro":"Walking through the food streets of Lahore at midnight, the clinking sound of flat metal spatulas against enormous iron tawas is unmistakable. Tawa Chicken Fry is fast, intense, and deeply satisfying—bursting with tanginess from lemons, tomatoes, and fiery green chilies.","ing":["Boneless chicken breast or thigh fillets cut into strips 750g","Cooking oil or ghee 4 tbsp","Ginger-garlic paste 2 tbsp","Ripe tomatoes finely chopped 3 medium","Spicy green chilies slit 6 pieces","Thick whisked yogurt 4 tbsp","Crushed red chili flakes 1 1/2 tsp, cumin seeds 1 tsp","Coriander seeds coarsely crushed 1 tbsp, chaat masala 1 tsp","Fresh lemon juice 3 tbsp, julienned ginger 2 tbsp, salt 1 tsp"],"steps":["Heat oil or ghee on a large iron flat griddle (tawa) or wide skillet over high flame.","Add cumin seeds and let them sizzle for 15 seconds. Add ginger-garlic paste and stir-fry for 1 minute.","Add chicken pieces and fry vigorously using two metal spatulas for 5 minutes until sealed and lightly browned.","Add chopped tomatoes, crushed coriander seeds, chili flakes, and salt. Mash the tomatoes with spatulas while tossing chicken continuously.","Add whisked yogurt and cook over high heat until gravy clings to each chicken piece and oil separates.","Add slit green chilies, lemon juice, and chaat masala. Toss rapidly for 2 minutes.","Garnish with abundant julienned ginger and fresh coriander. Serve sizzling right on the tawa with warm parathas."],"tip":"Cooking on high heat on a cast iron tawa is critical; it creates caramelized edges and quick reduction that standard non-stick pans cannot replicate.","published":"2026-11-10"},{"id":"crispy-jalebi","country":"India","name":"Crispy Halwai-Style Jalebi","cat":"meetha","catLabel":"Desserts","veg":"veg","time":35,"diff":"Medium","servings":"12-15 jalebis","img":"assets/crispy-jalebi-9c8d1e2f.webp","shape":"wide","alt":"Crispy golden spiral Jalebi soaked in saffron syrup with ZaikaWorlds logo","desc":"Golden-orange crispy spiral spirals made from fermented flour batter, deep-fried to crunchy coils in desi ghee, and instantly soaked in fragrant saffron-cardamom sugar syrup.","intro":"Crispy Jalebi is the crown jewel of morning breakfasts and festive evenings across South Asia. Piped directly into bubbling ghee in swift spiral spirals, then plunged into warm saffron-infused sugar syrup for that quintessential crunchy shell and warm, juicy center.","ing":["All-purpose flour (maida) 1 cup","Cornstarch or rice flour 2 tbsp for extra crunch","Thick yogurt whisked 1/4 cup","Baking powder 1/2 tsp","Desi ghee or vegetable oil for deep frying","Sugar 1 1/2 cups, water 1 cup","Saffron threads 1/4 tsp, green cardamom powder 1/2 tsp","Lemon juice 1 tsp (prevents sugar crystallization)","Edible orange/saffron food color a drop"],"steps":["Prepare sugar syrup: Combine sugar and water in a pan, bring to a boil, and simmer for 5 minutes until one-string consistency. Stir in saffron, cardamom powder, orange color, and lemon juice. Keep warm on lowest flame.","In a mixing bowl, whisk together flour, cornstarch, yogurt, baking powder, and 1/2 cup warm water into a smooth, thick, ribbon-consistency batter.","Pour batter into a piping cloth bag with a 3mm nozzle or a squeeze bottle.","Heat ghee in a flat-bottomed shallow frying pan over medium-high heat (350°F / 175°C).","Squeeze batter in swift circular motions from inside out to form spiral coils directly into hot ghee.","Fry for 2-3 minutes, flipping once, until golden and intensely crispy on both sides.","Remove crispy jalebis with tongs, shake off excess ghee, and immediately plunge into warm sugar syrup for 45-60 seconds.","Drain and transfer to a serving platter. Enjoy piping hot while delightfully crisp and juicy!"],"tip":"Dip the hot fried jalebis directly into warm (not boiling, not cold) sugar syrup; this ensures the syrup rushes inside the hollow crunchy tubes without making them soggy.","published":"2026-11-10"},{"id":"beef-boti-kabab","country":"Pakistan","name":"Bihari Beef Boti Kabab","cat":"bbq","catLabel":"BBQ","veg":"nonveg","time":40,"diff":"Medium","servings":"4 people","img":"assets/beef-boti-kabab-3f8a1e2d.webp","shape":"wide","alt":"Melt-in-mouth grilled Bihari Beef Boti Kabab with onions and ZaikaWorlds logo","desc":"Paper-thin slices of beef marinated in raw papaya, mustard oil, fried onions, and roasted poppy seeds, grilled on skewers to tender perfection.","intro":"Bihari Boti Kabab is legendary across South Asia for its astonishing melt-in-mouth softness. Marinated with raw papaya paste and pungent mustard oil, each bite dissolves effortlessly on the palate.","ing":["Boneless beef undercut sliced thin 750g","Raw green papaya paste 2 tbsp (natural tenderizer)","Pure mustard oil 3 tbsp","Golden fried onions crushed 1/2 cup","Thick hung yogurt 1/3 cup","Roasted gram flour (besan) 2 tbsp","Bihari kabab masala (crushed coriander, cumin, allspice, red chili) 2 tbsp","Ginger-garlic paste 1 1/2 tbsp, salt 1 tsp"],"steps":["Tenderize thin beef strips with raw papaya paste, ginger-garlic, and salt for 1 hour.","Mix in mustard oil, crushed fried onions, whisked yogurt, gram flour, and Bihari kabab masala.","Thread beef ribbon-style onto skewers. Cover and refrigerate for at least 4 hours.","Grill over hot charcoal embers for 10-12 minutes, turning and basting with butter until smoky charred.","Serve hot with fresh mint raita, parathas, and lemon."],"tip":"Raw papaya paste contains papain which tenderizes beef within hours; do not exceed 2 tablespoons or the meat will lose texture.","published":"2026-11-11"},{"id":"shahi-tukda","country":"India","name":"Royal Hyderabadi Shahi Tukda","cat":"meetha","catLabel":"Desserts","veg":"veg","time":30,"diff":"Easy","servings":"6 servings","img":"assets/shahi-tukda-7c1e8a2b.webp","shape":"wide","alt":"Ghee-fried golden toast soaked in saffron syrup and rich rabri with ZaikaWorlds logo","desc":"Crispy golden ghee-fried bread triangles soaked in saffron sugar syrup and blanketed with cardamom-scented rabri, pistachios, and silver leaf.","intro":"A regal Mughal creation celebrated in Hyderabad and Lucknow, Shahi Tukda translates literally to 'Royal Bite'. Thick bread slices fried crisp in pure desi ghee, dipped in fragrant saffron syrup, and bathed in slow-cooked creamy rabri.","ing":["White bread slices trimmed and cut into triangles 6 slices","Pure desi ghee for shallow frying","Full cream milk 1 liter reduced to thick rabri (1.5 cups)","Sugar 1 cup, water 3/4 cup","Saffron strands 1/4 tsp, green cardamom powder 1 tsp","Chopped pistachios and almonds 4 tbsp, silver vark"],"steps":["Fry bread triangles in desi ghee over medium flame until deep golden and crisp on both sides.","Make a one-string sugar syrup with water, sugar, saffron, and cardamom. Dip fried toast triangles for 30 seconds to soak.","Arrange soaked bread triangles in an overlapping fan on a royal serving platter.","Pour chilled, thick rabri generously over the center, leaving the golden crispy edges exposed.","Garnish lavishly with pistachios, slivered almonds, and silver leaf before serving."],"tip":"Leave the top pointed edges of the bread triangles untouched by rabri so each bite delivers both rich creaminess and crisp crunch.","published":"2026-11-11"},{"id":"dal-tadka","country":"India","name":"Dhaba Style Dal Tadka","cat":"desi","catLabel":"Desi Dishes","veg":"veg","time":35,"diff":"Easy","servings":"4 people","img":"assets/dal-tadka-8b2c1e9a.webp","shape":"wide","alt":"Golden yellow Dal Tadka with bubbling garlic cumin ghee tempering and ZaikaWorlds logo","desc":"Yellow toor and moong lentils cooked tender and tempered with smoking desi ghee, cumin seeds, garlic cloves, dried red chilies, and hing (asafoetida).","intro":"A highway dhaba classic that embodies pure comfort. Split yellow lentils cooked to creamy perfection, then finished with a smoking ghee tempering (tadka) of crushed garlic, whole red chilies, and aromatic cumin that sizzles as it hits the table.","ing":["Toor dal (pigeon pea) 1/2 cup, Yellow moong dal 1/2 cup","Water 3.5 cups, Turmeric powder 1/2 tsp, Salt 1 tsp","Desi ghee 3 tbsp","Cumin seeds 1 tsp, Mustard seeds 1/2 tsp","Garlic cloves finely chopped 6 pieces","Whole dried red chilies 3 pieces, Hing (asafoetida) a pinch","Tomatoes chopped 1 medium, Kashmiri chili powder 1/2 tsp","Fresh coriander leaves chopped 2 tbsp"],"steps":["Pressure cook or boil toor and moong dal with water, turmeric, and salt for 15-20 minutes until completely soft. Whisk gently.","In a small pan, heat desi ghee over medium flame until hot.","Add cumin seeds, mustard seeds, and hing; allow them to crackle.","Add chopped garlic and sauté until fragrant and golden brown.","Add dried red chilies and chopped tomatoes; cook for 2 minutes.","Stir in Kashmiri red chili powder for a vivid red color, then immediately pour the sizzling tadka over the dal.","Cover with lid for 2 minutes to lock in the smoky aroma, garnish with fresh coriander, and serve with jeera rice."],"tip":"Cover the pot immediately after pouring the hot sizzling tadka so the essential garlic-ghee fumes penetrate every drop of the lentils.","published":"2026-11-11"}];
